-- 5. CHỦ ĐỀ GÕ CÂU & CÂU LUYỆN TẬP THỰC TẾ (Kỳ vọng: 8 chủ đề, 48 câu)
INSERT INTO public.typing_topics (id, language, level, group_type, title, description, icon_name, sort_order) VALUES

  ('topic-en-shopping', 'en', 'A2 - B1', 'life', 'Mua sắm & Trả giá', 'Hỏi giá, kích cỡ, khuyến mãi và cách trả giá khéo léo trong cửa hàng.', NULL, 1),
  ('topic-en-restaurant', 'en', 'A2 - B1', 'life', 'Gọi món tại nhà hàng', 'Đặt bàn trước, hỏi món đặc trưng, yêu cầu gia vị và thanh toán hoá đơn.', NULL, 2),
  ('topic-en-email', 'en', 'B1 - B2', 'work', 'Soạn email công việc chuyên nghiệp', 'Mở đầu thư, đính kèm tài liệu, xác nhận lịch hẹn và lời kết trang trọng.', NULL, 3),
  ('topic-en-meeting', 'en', 'B2 - C1', 'work', 'Họp nhóm & Báo cáo tiến độ', 'Nêu ý kiến, ngắt lời lịch sự, trình bày biểu đồ và kết luận phiên họp.', NULL, 4),
  ('topic-zh-shopping', 'zh', 'HSK 2 - 3', 'life', 'Mua sắm & Mặc cả (买东西)', 'Hỏi giá, đổi trả và mặc cả tự nhiên tại chợ hoặc trung tâm thương mại.', NULL, 5),
  ('topic-zh-work', 'zh', 'HSK 3 - 4', 'work', 'Giao tiếp công sở & Báo cáo (商务办公)', 'Viết email, thảo luận tiến độ và bàn giao công việc với đối tác.', NULL, 6),
  ('topic-ja-restaurant', 'ja', 'N5 - N4', 'life', 'Nhà hàng & Quán ăn Nhật (レストラン)', 'Vào quán, gọi món theo set, xin thêm nước và gọi thanh toán O-kaikei.', NULL, 7),
  ('topic-ja-work', 'ja', 'N4 - N3', 'work', 'Hội thoại công việc & Kính ngữ (ビジネス)', 'Chào hỏi đồng nghiệp, báo cáo tiến độ và cảm ơn đối tác trang trọng.', NULL, 8)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description;

INSERT INTO public.typing_sentences (id, topic_id, content, reading, translation, hint_word, grammar_note, sort_order) VALUES

  ('eac24733-4cd3-50e5-9ac8-338f356e54ea', 'topic-en-shopping', 'Do you have this sweater in a smaller size?', '/duː juː hæv ðɪs ˈswetər ɪn ə ˈsmɔːlər saɪz/', 'Bạn có cái áo len này với kích thước nhỏ hơn không?', 'sweater', 'Cấu trúc hỏi đồ vật ở kích thước khác: "in a smaller/larger size".', 1),
  ('8eb26c2c-5aac-5d77-be25-44a4aedd095b', 'topic-en-shopping', 'Is this item currently on sale?', '/ɪz ðɪs ˈaɪtəm ˈkɜːrəntli ɒn seɪl/', 'Món đồ này có đang được áp dụng giảm giá không?', 'currently', '"on sale" có nghĩa là đang được giảm giá, khác với "for sale" (đang rao bán).', 2),
  ('b50a839c-8428-51ce-8b85-9ad054cdb0ef', 'topic-en-shopping', 'Can I try on this shirt in the fitting room?', '/kæn aɪ traɪ ɒn ðɪs ʃɜːrt ɪn ðə ˈfɪtɪŋ ruːm/', 'Tôi có thể thử chiếc áo sơ mi này trong phòng thay đồ được không?', 'try on', 'Cụm động từ "try on" dùng khi thử quần áo, giày dép.', 3),
  ('ac9d1ddf-50ff-5c8b-8e49-cbaabc9739ff', 'topic-en-shopping', 'If I buy two, could you give me a slight discount?', '/ɪf aɪ baɪ tuː kʊd juː ɡɪv miː ə slaɪt ˈdɪskaʊnt/', 'Nếu tôi mua hai chiếc, bạn có thể giảm giá thêm chút không?', 'slight discount', 'Dùng "could you" thể hiện lời đề nghị lịch sự, tế nhị.', 4),
  ('d9fc1bc2-1104-5c01-9a39-040f21cc4290', 'topic-en-shopping', 'What is your return policy for damaged goods?', '/wɒt ɪz jʊər rɪˈtɜːrn ˈpɒləsi fɔːr ˈdæmɪdʒd ɡʊdz/', 'Chính sách đổi trả hàng của cửa hàng là trong vòng bao nhiêu ngày?', 'return policy', '"return policy" là cụm danh từ chỉ chính sách đổi trả hàng.', 5),
  ('08ec73f6-6c69-561b-a0d0-895645f97653', 'topic-en-shopping', 'Can I pay by credit card without any surcharge?', '/kæn aɪ peɪ baɪ ˈkredɪt kɑːrd wɪˈðaʊt ˈeni ˈsɜːrtʃɑːrdʒ/', 'Tôi có thể thanh toán bằng thẻ tín dụng không trả phí phụ thu chứ?', 'surcharge', '"surcharge" là phụ phí dịch vụ hoặc phí cà thẻ.', 6),
  ('9c7d1516-9be0-573f-8f7e-cef9884f84eb', 'topic-en-shopping', 'Could you please gift wrap this item for me?', '/kʊd juː pliːz ɡɪft ræp ðɪs ˈaɪtəm fɔːr miː/', 'Làm ơn gói món này làm quà tặng giúp tôi nhé.', 'gift wrap', '"gift wrap" có thể dùng như động từ nghĩa là gói quà trang trọng.', 7),
  ('3373bd3b-0531-5d3f-b1b0-78d3549341c9', 'topic-en-shopping', 'I am looking for a pair of running shoes with good grip.', '/aɪ æm ˈlʊkɪŋ fɔːr ə peər əv ˈrʌnɪŋ ʃuːz wɪð ɡʊd ɡrɪp/', 'Tôi đang tìm kiếm một đôi giày chạy bộ có độ bám tốt.', 'good grip', '"grip" chỉ độ ma sát, độ bám đường chống trượt của đế giày.', 8),
  ('c6152851-53e5-5854-b72d-b580e9ec9b8e', 'topic-en-restaurant', 'I have a reservation for four under the name David at seven.', '/aɪ hæv ə ˌrezərˈveɪʃn fɔːr fɔːr ˈʌndər ðə neɪm ˈdeɪvɪd æt ˈsevn/', 'Tôi đã đặt một bàn cho bốn người dưới tên David lúc 7 giờ tối.', 'reservation', 'Cấu trúc đặt chỗ: "have a reservation for [số người] under the name [tên]".', 1),
  ('fdf302a0-f308-575e-a641-382c6f6cd549', 'topic-en-restaurant', 'What do you recommend as the chef special today?', '/wɒt duː juː ˌrekəˈmend æz ðə ʃef ˈspeʃl təˈdeɪ/', 'Hôm nay nhà hàng có món đặc biệt nào gợi ý cho chúng tôi không?', 'chef special', '"chef special" chỉ món sở trường đặc sắc trong ngày của bếp trưởng.', 2),
  ('5aca3c4d-ebff-5ee7-8588-80c2802110f4', 'topic-en-restaurant', 'I am allergic to seafood, does this contain shrimp or crab?', '/aɪ æm əˈlɜːrdʒɪk tuː ˈsiːfuːd dʌz ðɪs kənˈteɪn ʃrɪmp ɔːr kræb/', 'Tôi bị dị ứng với hải sản, món này có chứa tôm hay cua không?', 'allergic to', 'Cấu trúc "be allergic to something" diễn tả tình trạng dị ứng.', 3),
  ('bb99cf79-179c-572b-8b01-3f2fc93ea4c4', 'topic-en-restaurant', 'Could we please have the dressing on the side?', '/kʊd wiː pliːz hæv ðə ˈdresɪŋ ɒn ðə saɪd/', 'Làm ơn cho tôi nước sốt để riêng ở đĩa nhỏ bên cạnh nhé.', 'on the side', '"on the side" nghĩa là để nước chấm/nước sốt riêng không tưới trực tiếp.', 4),
  ('fa868063-bb34-5a1f-a98a-7e8e9059edab', 'topic-en-restaurant', 'Could you bring us another bottle of chilled still water?', '/kʊd juː brɪŋ ʌs əˈnʌðər ˈbɒtl əv tʃɪld stɪl ˈwɔːtər/', 'Bạn có thể mang thêm cho chúng tôi một chai nước suối ướp lạnh không?', 'still water', '"still water" là nước lọc không ga, đối lập với "sparkling water" (nước có ga).', 5),
  ('f594430d-00e2-525f-9e02-3708fcd9bf40', 'topic-en-restaurant', 'This steak is slightly overcooked compared to medium rare.', '/ðɪs steɪk ɪz ˈslaɪtli ˌoʊvərˈkʊkt kəmˈpeərd tuː ˈmiːdiəm reər/', 'Thịt bò bít tết này được chế biến hơi chín quá so với yêu cầu của tôi.', 'overcooked', '"overcooked" nghĩa là nấu quá lửa, "medium rare" là chín tái.', 6),
  ('9f9be0f3-f728-5911-ac38-ee63f88cd5e9', 'topic-en-restaurant', 'Could we please have the bill and split the check evenly?', '/kʊd wiː pliːz hæv ðə bɪl ænd splɪt ðə tʃek ˈiːvnli/', 'Chúng tôi có thể xin hoá đơn thanh toán và chia đôi tiền được không?', 'split the check', '"split the check/bill" là cách nói người Mỹ để chia đều hoá đơn.', 7),
  ('75b02b5e-6aba-5c48-8b08-9fc183a43b12', 'topic-en-restaurant', 'Everything was absolutely delicious, thank you for the wonderful service!', '/ˈevriθɪŋ wɒz ˌæbsəˈluːtli dɪˈlɪʃəs θæŋk juː fɔːr ðə ˈwʌndərfʊl ˈsɜːrvɪs/', 'Bữa tối hôm nay thực sự rất ngon miệng, cảm ơn sự phục vụ chu đáo!', 'absolutely', 'Dùng "absolutely" đi với các tính từ cực hạn (extreme adjectives) như "delicious".', 8),
  ('d385ce22-6dad-5162-a29b-7832e4f45c48', 'topic-en-email', 'I am writing to confirm our upcoming meeting this Friday.', '/aɪ æm ˈraɪtɪŋ tuː kənˈfɜːrm ˈaʊər ˈʌpˌkʌmɪŋ ˈmiːtɪŋ ðɪs ˈfraɪdeɪ/', 'Tôi viết email này để xác nhận lịch họp của chúng ta vào thứ Sáu tới.', 'upcoming', 'Mẫu câu mở đầu chuẩn tắc: "I am writing to + V-infinitive".', 1),
  ('07417822-a853-50c9-a2c2-876f0fabc6a2', 'topic-en-email', 'Please find attached the draft agreement for your review.', '/pliːz faɪnd əˈtætʃt ðə dræft əˈɡriːmənt fɔːr jʊər rɪˈvjuː/', 'Vui lòng xem tập tin đính kèm để biết thêm chi tiết dự thảo hợp đồng.', 'attached', 'Cách diễn đạt trang trọng khi đính kèm file trong thư thương mại.', 2),
  ('37d2f4cc-a8b8-5ac9-9ca3-659b8c14c62e', 'topic-en-email', 'I sincerely apologize for the delay in getting back to you.', '/aɪ sɪnˈsɪərli əˈpɒlədʒaɪz fɔːr ðə dɪˈleɪ ɪn ˈɡetɪŋ bæk tuː juː/', 'Tôi thành thật xin lỗi vì sự chậm trễ trong việc phản hồi thư của bạn.', 'apologize', '"get back to someone" là phản hồi lại thư hoặc cuộc gọi.', 3),
  ('f743a395-674f-5839-adeb-49ebb903eb35', 'topic-en-email', 'Should you require any further assistance, please do not hesitate to contact me.', '/ʃʊd juː rɪˈkwaɪər ˈeni ˈfɜːrðər əˈsɪstəns pliːz duː nɒt ˈhezɪteɪt tuː ˈkɒntækt miː/', 'Nếu bạn cần thêm bất kỳ thông tin nào, xin đừng ngần ngại liên hệ tôi.', 'hesitate', 'Đảo ngữ câu điều kiện loại 1 trang trọng: "Should you require...".', 4),
  ('88b45783-3ce6-5b7b-a1b8-d32257db16d9', 'topic-en-email', 'We greatly appreciate your prompt cooperation on this urgent matter.', '/wiː ˈɡreɪtli əˈpriːʃieɪt jʊər prɒmpt koʊˌɒpəˈreɪʃn ɒn ðɪs ˈɜːrdʒənt ˈmætər/', 'Chúng tôi rất trân trọng sự hợp tác kịp thời của bạn trong dự án này.', 'prompt cooperation', '"prompt" có nghĩa là nhanh chóng, không chậm trễ.', 5),
  ('b3b1ca3e-53e2-5162-a44b-3db12c2004f0', 'topic-en-email', 'I look forward to hearing your valuable feedback very soon.', '/aɪ lʊk ˈfɔːrwərd tuː ˈhɪərɪŋ jʊər ˈvæljuəbl ˈfiːdbæk ˈveri suːn/', 'Tôi mong nhận được phản hồi và ý kiến đóng góp quý báu từ bạn sớm.', 'feedback', 'Nhớ dùng "hearing" (V-ing) sau giới từ "to" trong cấu trúc "look forward to".', 6),
  ('32feea7b-ea50-58be-98f4-b5c096e916fd', 'topic-en-email', 'Could you please provide the updated budget by tomorrow afternoon?', '/kʊd juː pliːz prəˈvaɪd ðiː ʌpˈdeɪtɪd ˈbʌdʒɪt baɪ təˈmɒroʊ ˌæftərˈnuːn/', 'Bạn có thể vui lòng cập nhật lại ngân sách trước cuối ngày mai không?', 'budget', 'Giới từ "by" chỉ hạn chót (deadline) phải hoàn tất việc.', 7),
  ('e3ca6574-5d84-582b-9f8e-19247d4868bd', 'topic-en-email', 'Best regards, David Nguyen - Technical Lead.', '/best rɪˈɡɑːrdz ˈdeɪvɪd ŋuːˈjen ˈteknɪkl liːd/', 'Trân trọng kính thư, David Nguyen - Trưởng phòng kỹ thuật.', 'regards', '"Best regards" là lời chào kết thúc thư phổ biến và lịch thiệp nhất.', 8),
  ('bde4a84e-58e8-5fc2-bd03-eff5d4832d1c', 'topic-en-meeting', 'Let us kick off the meeting by reviewing our quarterly milestones.', '/let ʌs kɪk ɒf ðə ˈmiːtɪŋ baɪ rɪˈvjuːɪŋ ˈaʊər ˈkwɔːrtərli ˈmaɪlstoʊnz/', 'Chúng ta hãy bắt đầu cuộc họp bằng việc điểm lại các mục tiêu quý trước.', 'milestones', '"kick off" là cụm động từ tương đương "start / begin".', 1),
  ('951e6d9f-b901-5384-bc64-793f4ef06f23', 'topic-en-meeting', 'I could not agree more with your perspective on this strategy.', '/aɪ kʊd nɒt əˈɡriː mɔːr wɪð jʊər pərˈspektɪv ɒn ðɪs ˈstrætədʒi/', 'Tôi hoàn toàn đồng tình với quan điểm của bạn về vấn đề này.', 'perspective', '"could not agree more" là cách diễn tả sự đồng ý tuyệt đối.', 2),
  ('1419bd6d-c2e8-5fb5-8bb4-6223cbbd1cc7', 'topic-en-meeting', 'Sorry to interrupt, but I have a crucial point to clarify.', '/ˈsɒri tuː ˌɪntəˈrʌpt bʌt aɪ hæv ə ˈkruːʃl pɔɪnt tuː ˈklærɪfaɪ/', 'Xin lỗi vì đã cắt ngang lời, nhưng tôi có một điểm mấu chốt cần làm rõ.', 'interrupt', 'Cách ngắt lời chuyên nghiệp mà vẫn giữ phép lịch thiệp.', 3),
  ('e0c87c84-63ca-59a6-ae26-50d47f8a30fc', 'topic-en-meeting', 'As shown on the chart, active user engagement has surged dramatically.', '/æz ʃoʊn ɒn ðə tʃɑːrt ˈæktɪv ˈjuːzər ɪnˈɡeɪdʒmənt hæz sɜːrdʒd drəˈmætɪkli/', 'Theo như biểu đồ thể hiện, lượng người dùng tích cực đã tăng mạnh.', 'surged', '"surge" nghĩa là dâng cao đột biến, rất hay dùng trong báo cáo kinh doanh.', 4),
  ('4f8aa759-ec58-55ca-8a19-c7889a751d7d', 'topic-en-meeting', 'We must allocate more resources to meet the product launch deadline.', '/wiː mʌst ˈæləkeɪt mɔːr rɪˈsɔːrsɪz tuː miːt ðə ˈprɒdʌkt lɔːntʃ ˈdedlaɪn/', 'Chúng ta cần phân bổ thêm nhân lực để kịp tiến độ phát hành.', 'allocate', '"allocate resources" = phân bổ nguồn lực/nhân sự.', 5),
  ('15dfafe2-f8ab-5333-b596-9c82cb2138ac', 'topic-en-meeting', 'Let me summarize the action items assigned to each team member.', '/let miː ˈsʌməraɪz ðiː ˈækʃn ˈaɪtəmz əˈsaɪnd tuː iːtʃ tiːm ˈmembər/', 'Để tôi tóm tắt lại các đầu việc chính mà từng thành viên phụ trách.', 'action items', '"action items" là thuật ngữ chỉ các nhiệm vụ cụ thể được giao sau cuộc họp.', 6),
  ('3636fc14-f1d7-5320-bb4b-75081f6ac40e', 'topic-en-meeting', 'Does anyone have any further questions before we wrap up today?', '/dʌz ˈeniwʌn hæv ˈeni ˈfɜːrðər ˈkwestʃənz bɪˈfɔːr wiː ræp ʌp təˈdeɪ/', 'Có ai còn câu hỏi nào trước khi chúng ta kết thúc buổi họp không?', 'wrap up', '"wrap up" là cụm động từ thân mật để kết thúc một công việc hay cuộc họp.', 7),
  ('d0aa63e9-cfeb-5662-801b-400297791a88', 'topic-en-meeting', 'The detailed meeting minutes will be circulated via email shortly.', '/ðə ˈdiːteɪld ˈmiːtɪŋ ˈmɪnɪts wɪl biː ˈsɜːrkjəleɪtɪd ˈvaɪə ˈiːmeɪl ˈʃɔːrtli/', 'Biên bản cuộc họp chi tiết sẽ được gửi qua email cho tất cả các bên.', 'meeting minutes', '"meeting minutes" là biên bản cuộc họp.', 8),
  ('b4fa1730-4fc2-546c-a165-d02f56af54f9', 'topic-zh-shopping', '这件外套一件多少钱？', 'Zhè jiàn wàitào yī jiàn duōshǎo qián?', 'Chiếc áo khoác này bao nhiêu tiền một cái?', '多少钱', 'Lượng từ của áo khoác là 件 (jiàn).', 1),
  ('838a71dc-22ff-55d2-9dca-bca1293c05be', 'topic-zh-shopping', '太贵了，能不能便宜一点儿？', 'Tài guì le, néng bù néng piányi yīdiǎnr?', 'Đắt quá, bạn có thể tính rẻ hơn một chút được không?', '便宜', 'Mẫu câu trả giá kinh điển: 能不能便宜一点儿？', 2),
  ('3aac2a09-e9e7-506c-8ff3-efe17e310aaa', 'topic-zh-shopping', '我可以扫微信或者支付宝付款吗？', 'Wǒ kěyǐ sǎo wēixìn huòzhě zhīfùbǎo fùkuǎn ma?', 'Tôi có thể quét mã WeChat hoặc Alipay để thanh toán không?', '扫码', '扫 (sǎo) nghĩa là quét mã QR thanh toán.', 3),
  ('65129cd2-dafb-5ed5-8682-cc502bbaaa07', 'topic-zh-shopping', '这个尺码有点儿紧，有大一号的吗？', 'Zhège chǐmǎ yǒudiǎnr jǐn, yǒu dà yī hào de ma?', 'Kích cỡ này hơi chật, bạn có số lớn hơn một chút không?', '大一号', '大一号 (dà yī hào) nghĩa là số/size to hơn 1 cỡ.', 4),
  ('3bbbda20-637c-5546-ac44-a4fa65f1ef2f', 'topic-zh-work', '我已经把合同草案发到您的电子邮箱了。', 'Wǒ yǐjīng bǎ hétóng cǎo''àn fā dào nín de diànzǐ yóuxiāng le.', 'Tôi đã gửi hợp đồng dự thảo qua hòm thư điện tử của bạn rồi.', '把合同草案', 'Câu chữ 把 nhấn mạnh đối tượng bị chuyển vị trí.', 1),
  ('849521ae-ae32-50a1-8802-043940bb8dcc', 'topic-zh-work', '明早的会议因为技术原因推迟三十分钟。', 'Míngzǎo de huìyì yīnwèi jìshù yuányīn tuīchí sānshí fēnzhōng.', 'Cuộc họp sáng mai sẽ lùi lại ba mươi phút do sự cố kỹ thuật.', '推迟', '推迟 (tuīchí) nghĩa là hoãn lại, lùi giờ lại.', 2),
  ('ff3c3e41-b81f-5e74-80d7-c4317b93994b', 'topic-zh-work', '如果您有任何疑问，请随时与我们联系。', 'Rúguǒ nín yǒu rènhé yíwèn, qǐng suíshí yǔ wǒmen liánxì.', 'Nếu quý công ty có bất kỳ thắc mắc nào, xin vui lòng liên hệ kịp thời.', '联系', 'Cách nói trang trọng trong thư tín thương mại Trung Quốc.', 3),
  ('e96bbf99-a9d0-5c08-a61e-5341e7da4a43', 'topic-zh-work', '我们期待与贵公司建立长期的合作关系。', 'Wǒmen qīdài yǔ guì gōngsī jiànlì chángqī de hézuò guānxì.', 'Chúng tôi mong muốn thiết lập mối quan hệ hợp tác lâu dài với bạn.', '合作关系', '贵公司 (quý công ty) là đại từ tôn kính đối tác.', 4),
  ('0e996f5b-b475-5f74-8d1a-b56b5072133f', 'topic-ja-restaurant', 'すみません、英語のメニューはありますか？', 'Sumimasen, eigo no menyuu wa arimasu ka?', 'Xin lỗi, làm ơn cho tôi xem thực đơn tiếng Anh được không?', 'メニュー', 'すみません dùng mở đầu lời nhờ vả lịch sự.', 1),
  ('b6c85389-278e-52ee-9a0b-3436b72ff840', 'topic-ja-restaurant', 'とんかつ定食を二つお願いします。', 'Tonkatsu teishoku o futatsu onegaishimasu.', 'Làm ơn cho tôi hai suất cơm thịt lợn chiên xù Tonkatsu.', '二つ', 'Cách đếm đồ vật: 一つ (hitotsu), 二つ (futatsu).', 2),
  ('3ab96c3e-c36e-58ee-85ad-da7a7fa1af3c', 'topic-ja-restaurant', 'この料理はとても辛いですか？', 'Kono ryouri wa totemo karai desu ka?', 'Món này có cay lắm không ạ?', '辛い', '辛い (karai) nghĩa là vị cay.', 3),
  ('6ea22d03-25e8-5e29-a8f1-ca32c74d89f2', 'topic-ja-restaurant', 'お会計をお願いします。', 'O-kaikei o onegaishimasu.', 'Làm ơn tính tiền giúp tôi nhé.', 'お会計', 'お会計 (o-kaikei) là từ chuẩn khi thanh toán tại nhà hàng Nhật.', 4),
  ('925bab3d-7df6-5209-a3d6-697143adaec9', 'topic-ja-work', '本日もお疲れ様でした。', 'Honjitsu mo otsukaresama deshita.', 'Cảm ơn mọi người đã vất vả làm việc ngày hôm nay.', 'お疲れ様', 'Câu chào cửa miệng chuẩn tắc khi hết ca làm việc.', 1),
  ('905cf4e0-ac15-5497-a5dd-0740c42fea2f', 'topic-ja-work', '会議の資料をメールにてお送りいたします。', 'Kaigi no shiryou o meeru nite o-okuri itashimasu.', 'Tôi xin phép được gửi tài liệu buổi họp qua thư đính kèm.', 'お送りいたします', 'Khiêm nhường ngữ (Kenjougo): お + V-bỏ-masu + いたします.', 2),
  ('0de86994-a1fe-590c-85fa-ec9502677c06', 'topic-ja-work', '今後とも何卒よろしくお願い申し上げます。', 'Kongo tomo nanitazo yoroshiku onegai moushiagemasu.', 'Rất mong nhận được sự chỉ giáo và giúp đỡ tận tình từ quý vị.', '何卒', 'Lời kết email trang trọng bậc nhất trong văn hóa kinh doanh Nhật.', 3),
  ('002a3c3d-e3e4-51a1-b337-ed3c8a2b4ba4', 'topic-ja-work', '今回のプロジェクトについて、全力を尽くします。', 'Konkai no purojekuto ni tsuite, zenryoku o tsukushimasu.', 'Về dự án lần này, chúng tôi sẽ nỗ lực hết mình để kịp tiến độ.', '全力を尽くす', 'Cụm thành ngữ "全力を尽くす" nghĩa là nỗ lực dốc toàn lực.', 4)
ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, translation = EXCLUDED.translation, reading = EXCLUDED.reading, hint_word = EXCLUDED.hint_word, grammar_note = EXCLUDED.grammar_note;

-- 6. BỘ TỪ VỰNG HỆ THỐNG & TỪ VỰNG CHI TIẾT (Kỳ vọng: 5 bộ từ, 50 từ vựng)
INSERT INTO public.vocab_sets (id, user_id, level_id, title, description, is_system, language, is_public) VALUES

  ('a0000000-0000-0000-0000-000000000001', NULL, 3, 'Oxford 3000 từ vựng học thuật cốt lõi', 'Nền tảng từ vựng học thuật quan trọng nhất xuất hiện trong mọi bài thi và văn bản quốc tế.', true, 'en', true),
  ('a0000000-0000-0000-0000-000000000002', NULL, 5, 'Từ vựng tinh hoa IELTS 7.5+ Writing & Speaking', 'Các từ vựng học thuật cao cấp C1 giúp tăng điểm tiêu chí Lexical Resource trong kỳ thi IELTS.', true, 'en', true),
  ('a0000000-0000-0000-0000-000000000003', NULL, 4, 'Tiếng Anh thương mại & Giao tiếp công sở', 'Bộ từ vựng giao tiếp thực chiến nơi làm việc: đàm phán hợp đồng, quản lý dự án và báo cáo.', true, 'en', true),
  ('a0000000-0000-0000-0000-000000000004', NULL, 4, 'HSK 3 - 4 Từ vựng cốt lõi khẩu ngữ & đời sống', 'Bộ từ vựng Hán ngữ thông dụng nhất trong giao tiếp hàng ngày và thương mại.', true, 'zh', true),
  ('a0000000-0000-0000-0000-000000000005', NULL, 4, 'JLPT N3 - N2 Từ vựng thông dụng trong đời sống & Công ty', 'Từ vựng thiết yếu giúp bạn vượt qua kỳ thi năng lực tiếng Nhật và làm việc tại Nhật.', true, 'ja', true)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description;

INSERT INTO public.vocab_words (id, set_id, word, phonetic, part_of_speech, meaning_vi, example_sentence, example_translation, reading, examples) VALUES

  ('b0000001-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'Resilient', '/rɪˈzɪliənt/', 'adj', 'Kiên cường, có khả năng phục hồi nhanh chóng sau nghịch cảnh.', 'Local communities have proven remarkably resilient in the face of natural disasters.', 'Các cộng đồng địa phương đã chứng minh sự kiên cường đáng nể trước thiên tai.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000001', 'Allocate', '/ˈæləkeɪt/', 'verb', 'Phân bổ, chỉ định nguồn vốn hoặc tài nguyên cho mục đích cụ thể.', 'The government decided to allocate more funds to renewable energy research.', 'Chính phủ đã quyết định phân bổ thêm ngân quỹ cho nghiên cứu năng lượng tái tạo.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000001', 'Comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adj', 'Toàn diện, bao hàm đầy đủ mọi khía cạnh.', 'The university offers a comprehensive guide to international student admissions.', 'Trường đại học cung cấp một cuốn cẩm nang toàn diện về tuyển sinh du học sinh.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000004', 'a0000000-0000-0000-0000-000000000001', 'Diminish', '/dɪˈmɪnɪʃ/', 'verb', 'Làm giảm bớt, suy yếu về số lượng hoặc tầm ảnh hưởng.', 'His influence in the company did not diminish despite recent controversies.', 'Ảnh hưởng của ông ấy tại công ty không hề giảm sút dù vướng phải những tranh cãi gần đây.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000005', 'a0000000-0000-0000-0000-000000000001', 'Facilitate', '/fəˈsɪlɪteɪt/', 'verb', 'Tạo điều kiện thuận lợi, làm cho một quá trình trở nên dễ dàng hơn.', 'Digital tools help facilitate smoother communication among remote employees.', 'Các công cụ kỹ thuật số giúp tạo điều kiện giao tiếp trôi chảy hơn giữa nhân viên làm việc từ xa.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000006', 'a0000000-0000-0000-0000-000000000001', 'Implicit', '/ɪmˈplɪsɪt/', 'adj', 'Ngấm ngầm, ẩn ý, không nói toạc ra nhưng ai cũng hiểu.', 'There was an implicit agreement that no one would bring up the painful topic.', 'Có một sự ngầm đồng thuận rằng không ai được phép nhắc lại chủ đề đau buồn ấy.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000007', 'a0000000-0000-0000-0000-000000000001', 'Legitimate', '/lɪˈdʒɪtɪmət/', 'adj', 'Hợp pháp, chính đáng, có căn cứ xác đáng.', 'The consumers raised legitimate concerns regarding data privacy violations.', 'Người tiêu dùng đã nêu lên những quan ngại chính đáng liên quan đến vi phạm quyền riêng tư.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000008', 'a0000000-0000-0000-0000-000000000001', 'Perspective', '/pərˈspektɪv/', 'noun', 'Góc nhìn, quan điểm cá nhân đối với một sự vật hiện tượng.', 'Traveling abroad helps people gain a much broader perspective on diverse cultures.', 'Đi du lịch nước ngoài giúp con người có được góc nhìn rộng mở hơn về các nền văn hóa đa dạng.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000009', 'a0000000-0000-0000-0000-000000000001', 'Subsequent', '/ˈsʌbsɪkwənt/', 'adj', 'Xảy ra sau đó, tiếp theo theo trình tự thời gian.', 'Subsequent investigations confirmed that the initial report was entirely accurate.', 'Các cuộc điều tra tiếp theo sau đó đã xác nhận rằng bản báo cáo ban đầu hoàn toàn chính xác.', NULL, '[]'::jsonb),
  ('b0000001-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'Underlying', '/ˌʌndərˈlaɪɪŋ/', 'adj', 'Căn bản, nằm sâu bên dưới, là gốc rễ của vấn đề.', 'Stress is often the underlying cause of many chronic health issues.', 'Căng thẳng thường là nguyên nhân gốc rễ sâu xa của nhiều vấn đề sức khỏe mãn tính.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000002', 'Plausible', '/ˈplɔːzəbl/', 'adj', 'Hợp lý, có vẻ đúng, đáng tin cậy.', 'The scientist offered a plausible hypothesis for the sudden extinction event.', 'Nhà khoa học đã đưa ra một giả thuyết hợp lý cho sự kiện tuyệt chủng đột ngột.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'Mitigate', '/ˈmɪtɪɡeɪt/', 'verb', 'Làm giảm nhẹ bớt tác hại hoặc mức độ nghiêm trọng.', 'Reforestation plays an indispensable role in mitigating climate change impacts.', 'Tái trồng rừng đóng vai trò không thể thiếu trong việc giảm nhẹ tác động của biến đổi khí hậu.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000002', 'Detrimental', '/ˌdetrɪˈmentl/', 'adj', 'Có hại, gây tổn hại nghiêm trọng.', 'Sedentary lifestyles have a distinctly detrimental effect on cognitive functions.', 'Lối sống ít vận động gây ra tác hại rõ rệt đối với các chức năng nhận thức não bộ.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000004', 'a0000000-0000-0000-0000-000000000002', 'Ubiquitous', '/juːˈbɪkwɪtəs/', 'adj', 'Có mặt ở khắp mọi nơi, cực kỳ phổ biến.', 'Artificial intelligence is becoming increasingly ubiquitous in daily applications.', 'Trí tuệ nhân tạo đang ngày càng trở nên phổ biến ở khắp nơi trong các ứng dụng thường nhật.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000005', 'a0000000-0000-0000-0000-000000000002', 'Pragmatic', '/præɡˈmætɪk/', 'adj', 'Thực tế, thực dụng, dựa trên tính khả thi thay vì lý thuyết.', 'Policymakers must adopt a pragmatic mindset when revising public healthcare laws.', 'Các nhà hoạch định chính sách phải áp dụng tư duy thực tế khi sửa đổi luật y tế công cộng.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000006', 'a0000000-0000-0000-0000-000000000002', 'Juxtapose', '/ˌdʒʌkstəˈpoʊz/', 'verb', 'Đặt cạnh nhau để so sánh sự tương phản rõ rệt.', 'The exhibition juxtaposes contemporary modern art with traditional woodcut prints.', 'Buổi triển lãm đặt nghệ thuật đương đại cạnh tranh khắc gỗ truyền thống để thấy sự đối lập.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000007', 'a0000000-0000-0000-0000-000000000002', 'Superfluous', '/suːˈpɜːrfluəs/', 'adj', 'Thừa thãi, không cần thiết, vượt quá mức đòi hỏi.', 'Eliminating superfluous packaging helps reduce millions of tons of plastic waste.', 'Cắt giảm bao bì thừa thãi giúp giảm thiểu hàng triệu tấn rác thải nhựa.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000008', 'a0000000-0000-0000-0000-000000000002', 'Discrepancy', '/dɪˈskrepənsi/', 'noun', 'Sự sai lệch, bất đồng giữa hai số liệu hoặc câu chuyện.', 'Auditors uncovered a noticeable discrepancy between the receipts and bank records.', 'Các kiểm toán viên đã phát hiện sự sai lệch đáng chú ý giữa biên lai và sổ sách ngân hàng.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000009', 'a0000000-0000-0000-0000-000000000002', 'Exacerbate', '/ɪɡˈzæsərbeɪt/', 'verb', 'Làm trầm trọng thêm, khiến tình hình xấu đi.', 'Heavy industrial emissions will inevitably exacerbate the existing smog epidemic.', 'Khí thải công nghiệp nặng chắc chắn sẽ làm trầm trọng thêm dịch khói mù hiện tại.', NULL, '[]'::jsonb),
  ('b0000002-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000002', 'Prevalent', '/ˈprevələnt/', 'adj', 'Thịnh hành, lan tràn rộng khắp trong cộng đồng.', 'Anxiety disorders are increasingly prevalent among urban adolescents today.', 'Rối loạn lo âu đang ngày càng lan tràn phổ biến trong giới thanh thiếu niên đô thị ngày nay.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000003', 'Streamline', '/ˈstriːmlaɪn/', 'verb', 'Tinh gọn hoá, đơn giản hoá quy trình để tăng hiệu suất.', 'We need to streamline our internal approval process to speed up deliveries.', 'Chúng ta cần tinh gọn hoá quy trình phê duyệt nội bộ để đẩy nhanh tiến độ giao hàng.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000003', 'Leverage', '/ˈlevərɪdʒ/', 'verb', 'Tận dụng tối đa đòn bẩy hoặc lợi thế có sẵn.', 'The startup managed to leverage strategic partnerships to expand overseas.', 'Công ty khởi nghiệp đã tận dụng quan hệ đối tác chiến lược để mở rộng ra nước ngoài.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000003', 'Bottleneck', '/ˈbɒtlnek/', 'noun', 'Điểm nghẽn, nơi làm chậm toàn bộ dây chuyền hoạt động.', 'Manual quality control testing became the main bottleneck in our production line.', 'Kiểm thử chất lượng thủ công đã trở thành điểm nghẽn chính trên dây chuyền sản xuất.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000004', 'a0000000-0000-0000-0000-000000000003', 'Consensus', '/kənˈsensəs/', 'noun', 'Sự đồng thuận chung của cả tập thể.', 'After two hours of intense debate, the board reached a unanimous consensus.', 'Sau hai giờ tranh luận căng thẳng, ban giám đốc đã đạt được sự đồng thuận nhất trí.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000005', 'a0000000-0000-0000-0000-000000000003', 'Benchmark', '/ˈbentʃmɑːrk/', 'noun', 'Tiêu chuẩn đối sánh, chuẩn mực để so sánh đánh giá.', 'Their customer satisfaction rating serves as a reliable benchmark for our industry.', 'Tỷ lệ hài lòng khách hàng của họ được dùng làm chuẩn đối sánh đáng tin cậy cho ngành.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000006', 'a0000000-0000-0000-0000-000000000003', 'Viable', '/ˈvaɪəbl/', 'adj', 'Khả thi, có khả năng tồn tại và sinh lời lâu dài.', 'Subscription pricing turned out to be a financially viable business model.', 'Thu phí định kỳ đã chứng minh là một mô hình kinh doanh khả thi về mặt tài chính.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000007', 'a0000000-0000-0000-0000-000000000003', 'Contingency', '/kənˈtɪndʒənsi/', 'noun', 'Kế hoạch dự phòng cho tình huống bất ngờ có thể xảy ra.', 'Every risk assessment must include a solid contingency plan for server outages.', 'Mọi đánh giá rủi ro đều phải bao gồm kế hoạch dự phòng vững chắc cho sự cố sập máy chủ.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000008', 'a0000000-0000-0000-0000-000000000003', 'Scalable', '/ˈskeɪləbl/', 'adj', 'Có khả năng mở rộng quy mô mà không giảm hiệu năng.', 'Cloud infrastructure provides a highly scalable solution for rapid user growth.', 'Hạ tầng điện toán đám mây cung cấp giải pháp mở rộng quy mô linh hoạt khi người dùng tăng.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000009', 'a0000000-0000-0000-0000-000000000003', 'Accountability', '/əˌkaʊntəˈbɪləti/', 'noun', 'Trách nhiệm giải trình, chịu trách nhiệm về kết quả hành động.', 'Clear ownership fosters individual accountability across cross-functional teams.', 'Phân quyền rõ ràng thúc đẩy tinh thần trách nhiệm giải trình cá nhân giữa các phòng ban.', NULL, '[]'::jsonb),
  ('b0000003-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000003', 'Incentive', '/ɪnˈsentɪv/', 'noun', 'Động lực khuyến khích, phần thưởng kích thích làm việc.', 'Performance-based bonuses provide a strong financial incentive for sales teams.', 'Thưởng theo hiệu quả đem lại động lực tài chính mạnh mẽ cho đội ngũ kinh doanh.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000004', '坚持', 'jiān chí', 'động từ', 'Kiên trì, giữ vững quyết tâm không từ bỏ.', '只要坚持努力，你终会取得令人瞩目的成绩。', 'Chỉ cần kiên trì nỗ lực, bạn cuối cùng sẽ đạt thành tích đáng nể.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000004', '深刻', 'shēn kè', 'tính từ', 'Sâu sắc, để lại dấu ấn khó phai.', '这次经历给我留下了极为深刻的记忆。', 'Trải nghiệm lần này đã để lại cho tôi ký ức vô cùng sâu sắc.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000004', '适应', 'shì yìng', 'động từ', 'Thích nghi, quen dần với môi trường mới.', '来到新城市后，他很快便适应了那里的生活节奏。', 'Sau khi đến thành phố mới, anh ấy nhanh chóng thích nghi với nhịp sống nơi đó.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000004', 'a0000000-0000-0000-0000-000000000004', '积累', 'jī lěi', 'động từ / danh từ', 'Tích luỹ từng chút một theo thời gian.', '学习语言需要日积月累，不可急于求成。', 'Học ngôn ngữ cần tích luỹ từng ngày, không thể nóng vội.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000005', 'a0000000-0000-0000-0000-000000000004', '沟通', 'gōu tōng', 'động từ', 'Giao tiếp, trao đổi thấu hiểu lẫn nhau.', '良好的沟通是解决团队矛盾的关键钥匙。', 'Giao tiếp tốt là chìa khoá then chốt để giải quyết mâu thuẫn nhóm.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000006', 'a0000000-0000-0000-0000-000000000004', '详细', 'xiáng xì', 'tính từ', 'Chi tiết, tường tận, không bỏ sót điều gì.', '请为您负责的方案制定一份详细的执行计划。', 'Xin vui lòng lập một kế hoạch thực hiện chi tiết cho phương án của bạn.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000007', 'a0000000-0000-0000-0000-000000000004', '陪同', 'péi tóng', 'động từ', 'Đi cùng, tháp tùng ai đó một cách chu đáo.', '总经理在助手的陪同下视察了新建的研发中心。', 'Tổng giám đốc dưới sự tháp tùng của trợ lý đã thị sát trung tâm R&D mới xây.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000008', 'a0000000-0000-0000-0000-000000000004', '丰富', 'fēng fù', 'tính từ / động từ', 'Phong phú, dồi dào về kiến thức hoặc nội dung.', '经常阅读课外书籍可以丰富我们的精神世界。', 'Thường xuyên đọc sách ngoài giờ có thể làm phong phú thế giới tinh thần của chúng ta.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000009', 'a0000000-0000-0000-0000-000000000004', '诚恳', 'chéng kěn', 'tính từ', 'Chân thành, thành thật từ tận đáy lòng.', '他诚恳的态度打动了在场所有的评委老师。', 'Thái độ chân thành của anh ấy đã làm xúc động tất cả thầy cô giám khảo có mặt.', NULL, '[]'::jsonb),
  ('b0000004-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000004', '关键', 'guān jiàn', 'danh từ / tính từ', 'Then chốt, mấu chốt quyết định thành bại.', '在关键时刻保持冷静是优秀领导者的特质。', 'Giữ được bình tĩnh vào thời khắc then chốt là phẩm chất của nhà lãnh đạo ưu tú.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000005', '改善', 'かいぜん (Kaizen)', 'danh từ / suru', 'Cải tiến liên tục để ngày càng tốt hơn.', '作業の効率を改善するため、新しい手順を導入した。', 'Để cải thiện hiệu suất công việc, chúng tôi đã đưa vào quy trình mới.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000005', '思いやり', 'おもいやり (Omoiyari)', 'danh từ', 'Sự thấu hiểu, chu đáo và biết nghĩ cho người khác.', '相手への思いやりを持って接することが信頼につながる。', 'Ứng xử với sự quan tâm nghĩ cho đối phương sẽ dẫn đến sự tin tưởng.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000005', '柔軟', 'じゅうなん (Juunan)', 'tính từ na', 'Mềm dẻo, linh hoạt ứng biến theo tình huống.', '予期せぬ変化にも柔軟に対応できる姿勢が求められる。', 'Cần có tinh thần ứng biến linh hoạt trước những đổi thay bất ngờ.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000004', 'a0000000-0000-0000-0000-000000000005', '妥協', 'だきょう (Dakyou)', 'danh từ / suru', 'Thoả hiệp, nhượng bộ để đạt điểm chung.', '双方が譲り合い、ようやく妥協点に達した。', 'Cả hai bên cùng nhượng bộ và cuối cùng đã đạt được điểm thoả hiệp.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000005', 'a0000000-0000-0000-0000-000000000005', '貢献', 'こうけん (Kouken)', 'danh từ / suru', 'Cống hiến, đóng góp tích cực cho xã hội.', '地域社会の発展に貢献する活動に積極的に参加している。', 'Chúng tôi tích cực tham gia các hoạt động đóng góp cho sự phát triển địa phương.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000006', 'a0000000-0000-0000-0000-000000000005', '的確', 'てきかく (Tekikaku)', 'tính từ na', 'Chính xác, trúng đích, xác đáng.', '状況を的確に把握し、速やかに次の手を打つ必要がある。', 'Cần nắm bắt tình hình một cách chính xác và nhanh chóng triển khai bước tiếp theo.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000007', 'a0000000-0000-0000-0000-000000000005', '把握', 'はあく (Haaku)', 'danh từ / suru', 'Nắm vững, thấu suốt toàn diện vấn đề.', 'プロジェクトの進捗状況をリアルタイムで把握する。', 'Nắm bắt tiến độ của dự án theo thời gian thực.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000008', 'a0000000-0000-0000-0000-000000000005', '迅速', 'じんそく (Jinsoku)', 'tính từ na', 'Nhanh chóng, thần tốc, không chần chừ.', '顧客からの問い合わせには迅速に対応しなければならない。', 'Phải phản hồi một cách nhanh chóng các thắc mắc từ phía khách hàng.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000009', 'a0000000-0000-0000-0000-000000000005', '誠実', 'せいじつ (Seijitsu)', 'tính từ na', 'Thành thực, chân thành và đáng tin cậy.', '誠実な仕事ぶりが高く評価され、昇進が決まった。', 'Tác phong làm việc chân chính được đánh giá cao và anh đã được thăng chức.', NULL, '[]'::jsonb),
  ('b0000005-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000005', '綿密', 'めんみつ (Menmitsu)', 'tính từ na', 'Tỉ mỉ, chu đáo, cẩn thận từng chi tiết nhỏ.', '綿密な計画を立ててから実行に移すことが成功の秘訣だ。', 'Lập kế hoạch tỉ mỉ chu đáo trước khi thực hiện là bí quyết của thành công.', NULL, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET meaning_vi = EXCLUDED.meaning_vi, example_sentence = EXCLUDED.example_sentence, phonetic = EXCLUDED.phonetic;

-- 7. CẤP ĐỘ NGỮ PHÁP (GRAMMAR LEVELS) (Kỳ vọng: 6 bản ghi)
INSERT INTO public.grammar_levels (language, code, name, description, sort_order) VALUES

  ('en', 'A1', 'Cấp độ A1 - Nền tảng sơ cấp', 'Làm quen với cấu trúc câu đơn, động từ To Be, thì hiện tại đơn và đại từ nhân xưng.', 1),
  ('en', 'A2', 'Cấp độ A2 - Giao tiếp mở rộng', 'Nắm vững thì quá khứ đơn, so sánh hơn/nhất, động từ khuyết thiếu và thì hiện tại tiếp diễn.', 2),
  ('zh', 'HSK 1', 'HSK 1 - Nhập môn Hán ngữ', 'Đại từ nhân xưng, trợ từ 是 (shì), 的 (de) và trợ từ nghi vấn 吗 (ma).', 1),
  ('zh', 'HSK 2', 'HSK 2 - Cấu trúc mở rộng', 'Bổ ngữ chỉ thời lượng, câu so sánh 比 (bǐ), câu chữ 把 (bǎ) cơ bản.', 2),
  ('ja', 'N5', 'Cấp độ JLPT N5 - Nhập môn', 'Các trợ từ cơ bản は, が, を, に, で và các thể lịch sự です / ます.', 1),
  ('ja', 'N4', 'Cấp độ JLPT N4 - Trung sơ cấp', 'Thể điều kiện (たら, ば), thể khả năng, thể bị động và thể sai khiến.', 2)
ON CONFLICT (language, code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;

-- 8. ĐIỂM NGỮ PHÁP & BÀI TẬP THỰC CHIẾN (Kỳ vọng: 24 điểm, 28 bài tập)
INSERT INTO public.grammar_points (id, language, level, title, vietnamese_title, summary, formula, explanation, explanation_notes, examples, common_mistakes, xp_reward, sort_order) VALUES

  ('en-a1-tobe', 'en', 'A1', 'Động từ "To Be" ở thì Hiện tại đơn', 'Cấu trúc Am / Is / Are trong câu khẳng định, phủ định và nghi vấn', 'Động từ "to be" biểu thị trạng thái, tính chất hoặc danh tính của chủ ngữ.', '{"pattern":"S + am / is / are + Noun / Adjective","tokens":[{"label":"Subject (I/He/She/They...)","role":"subject"},{"label":"am / is / are","role":"verb"},{"label":"Danh từ / Tính từ bổ nghĩa","role":"object"}]}'::jsonb, 'Chủ ngữ "I" đi với "am".
Chủ ngữ số ít (He, She, It, danh từ số ít) đi với "is".
Chủ ngữ số nhiều (You, We, They, danh từ số nhiều) đi với "are".
Phủ định: thêm "not" ngay sau động từ to be (am not, isn''t, aren''t).', '["Chủ ngữ \"I\" đi với \"am\".","Chủ ngữ số ít (He, She, It, danh từ số ít) đi với \"is\".","Chủ ngữ số nhiều (You, We, They, danh từ số nhiều) đi với \"are\".","Phủ định: thêm \"not\" ngay sau động từ to be (am not, isn''t, aren''t)."]'::jsonb, '[{"target":"She is a talented architect.","vi":"Cô ấy là một kiến trúc sư tài năng.","phonetic":"/ʃiː ɪz ə ˈtæləntɪd ˈɑːrkɪtekt/"},{"target":"They are very friendly to newcomers.","vi":"Họ rất thân thiện với những người mới đến.","phonetic":"/ðeɪ ɑːr ˈveri ˈfrendli tuː ˈnuːkʌmərz/"}]'::jsonb, '[{"wrong":"They is teachers at my local school.","correct":"They are teachers at my local school.","explanation":"Chủ ngữ \"They\" là ngôi thứ 3 số nhiều nên bắt buộc dùng \"are\", không dùng \"is\"."}]'::jsonb, 30, 1),
  ('en-a1-present-simple', 'en', 'A1', 'Thì Hiện tại đơn (Present Simple)', 'Diễn tả thói quen thường nhật và chân lý bất biến', 'Dùng động từ nguyên mẫu (V) cho I/You/We/They và thêm -s/-es cho He/She/It.', '{"pattern":"S + V(s/es) + Object","tokens":[{"label":"Subject","role":"subject"},{"label":"Verb (thêm -s / -es khi cần)","role":"verb"},{"label":"Object / Complement","role":"object"}]}'::jsonb, 'Thêm "-es" vào sau các động từ tận cùng bằng: -o, -s, -z, -ch, -x, -sh (ví dụ: go -> goes, watch -> watches).
Câu phủ định mượn trợ động từ "do not (don''t)" hoặc "does not (doesn''t)".
Các trạng từ chỉ tần suất hay đi kèm: always, usually, often, sometimes, never.', '["Thêm \"-es\" vào sau các động từ tận cùng bằng: -o, -s, -z, -ch, -x, -sh (ví dụ: go -> goes, watch -> watches).","Câu phủ định mượn trợ động từ \"do not (don''t)\" hoặc \"does not (doesn''t)\".","Các trạng từ chỉ tần suất hay đi kèm: always, usually, often, sometimes, never."]'::jsonb, '[{"target":"My father reads the morning newspaper every single day.","vi":"Bố tôi đọc báo buổi sáng vào mỗi ngày.","phonetic":"/maɪ ˈfɑːðər riːdz ðə ˈmɔːrnɪŋ ˈnjuːzpeɪpər ˈevri ˈsɪŋɡl deɪ/"}]'::jsonb, '[{"wrong":"He don''t likes waking up early.","correct":"He doesn''t like waking up early.","explanation":"Với ngôi \"He\", trợ động từ phủ định là \"doesn''t\", và động từ chính trở về nguyên mẫu \"like\"."}]'::jsonb, 30, 2),
  ('en-a1-articles', 'en', 'A1', 'Mạo từ A, An, The trong tiếng Anh', 'Quy tắc phân biệt mạo từ không xác định và mạo từ xác định', 'Dùng "a/an" cho danh từ đếm được số ít chưa xác định, dùng "the" cho đối tượng đã biết rõ.', '{"pattern":"A / An (nguyên âm) + Danh từ đếm được số ít","tokens":[{"label":"a / an / the","role":"particle"},{"label":"Noun (Danh từ)","role":"object"}]}'::jsonb, 'Dùng "an" trước các từ phát âm bắt đầu bằng một nguyên âm (/e/, /æ/, /aɪ/, /ɒ/...) ví dụ: an hour (h câm), an apple.
Dùng "a" trước từ phát âm bắt đầu bằng phụ âm, ví dụ: a university (/juː.../ là bán phụ âm).
Dùng "the" khi đối tượng là duy nhất (the sun, the earth) hoặc đã được nhắc đến ở câu trước.', '["Dùng \"an\" trước các từ phát âm bắt đầu bằng một nguyên âm (/e/, /æ/, /aɪ/, /ɒ/...) ví dụ: an hour (h câm), an apple.","Dùng \"a\" trước từ phát âm bắt đầu bằng phụ âm, ví dụ: a university (/juː.../ là bán phụ âm).","Dùng \"the\" khi đối tượng là duy nhất (the sun, the earth) hoặc đã được nhắc đến ở câu trước."]'::jsonb, '[{"target":"I saw an owl sitting on the roof last night.","vi":"Tối qua tôi nhìn thấy một con cú đang đậu trên mái nhà."}]'::jsonb, '[{"wrong":"She wants to study at an university in Europe.","correct":"She wants to study at a university in Europe.","explanation":"\"University\" phiên âm bắt đầu bằng âm phụ âm /j/ nên phải dùng \"a\"."}]'::jsonb, 30, 3),
  ('en-a1-pronouns', 'en', 'A1', 'Đại từ nhân xưng & Tính từ sở hữu', 'Phân biệt Subject, Object Pronouns và Possessive Adjectives', 'Đại từ làm chủ ngữ (I, you, he), tân ngữ (me, you, him) và tính từ sở hữu (my, your, his).', '{"pattern":"Subject Pronoun + Verb + Object Pronoun","tokens":[{"label":"S-Pronoun (I/He/She)","role":"subject"},{"label":"Verb","role":"verb"},{"label":"O-Pronoun (me/him/them)","role":"object"}]}'::jsonb, 'Tính từ sở hữu (my, his, her, their) bắt buộc phải đi kèm một danh từ phía sau.
Tân ngữ (me, him, her, us, them) đứng sau động từ hoặc giới từ.', '["Tính từ sở hữu (my, his, her, their) bắt buộc phải đi kèm một danh từ phía sau.","Tân ngữ (me, him, her, us, them) đứng sau động từ hoặc giới từ."]'::jsonb, '[{"target":"Our teacher gave us very helpful advice.","vi":"Giáo viên của chúng tôi đã cho chúng tôi lời khuyên rất hữu ích."}]'::jsonb, '[{"wrong":"Her invited me and he to the party.","correct":"She invited me and him to the party.","explanation":"Đầu câu làm chủ ngữ phải là \"She\", sau động từ làm tân ngữ phải là \"him\"."}]'::jsonb, 30, 4),
  ('en-a2-past-simple', 'en', 'A2', 'Thì Quá khứ đơn (Past Simple)', 'Diễn tả hành động đã kết thúc hoàn toàn trong quá khứ', 'Thêm -ed cho động từ có quy tắc hoặc dùng dạng V2 của bảng động từ bất quy tắc.', '{"pattern":"S + V2 / V-ed + (thời gian quá khứ: yesterday, in 2020...)","tokens":[{"label":"Subject","role":"subject"},{"label":"Verb (V-ed / V2 bất quy tắc)","role":"verb"},{"label":"Thời gian quá khứ","role":"modifier"}]}'::jsonb, 'Dấu hiệu nhận biết: yesterday, last night/week, ago, in the past, in + năm quá khứ.
Phủ định dùng: did not (didn''t) + V-nguyên mẫu.
Nghi vấn: Did + S + V-nguyên mẫu?', '["Dấu hiệu nhận biết: yesterday, last night/week, ago, in the past, in + năm quá khứ.","Phủ định dùng: did not (didn''t) + V-nguyên mẫu.","Nghi vấn: Did + S + V-nguyên mẫu?"]'::jsonb, '[{"target":"We bought a cozy little house by the sea two years ago.","vi":"Chúng tôi đã mua một căn nhà nhỏ ấm cúng bên bờ biển hai năm trước.","phonetic":"/wiː bɔːt ə ˈkoʊzi ˈlɪtl haʊs baɪ ðə siː tuː jɪərz əˈɡoʊ/"}]'::jsonb, '[{"wrong":"We didn''t went to the concert last Saturday.","correct":"We didn''t go to the concert last Saturday.","explanation":"Sau trợ động từ \"didn''t\", động từ chính bắt buộc phải trở về nguyên mẫu \"go\"."}]'::jsonb, 30, 1),
  ('en-a2-comparatives', 'en', 'A2', 'So sánh hơn và So sánh nhất của Tính từ', 'Quy tắc thêm -er/-est và dùng more/most cho tính từ ngắn/dài', 'Tính từ ngắn thêm -er/-est (tall -> taller -> tallest); tính từ dài dùng more/most.', '{"pattern":"S1 + be + Adj-er / more Adj + than + S2","tokens":[{"label":"Subject 1","role":"subject"},{"label":"Adj-er / More Adj","role":"verb"},{"label":"than","role":"particle"},{"label":"Subject 2","role":"object"}]}'::jsonb, 'Tính từ bất quy tắc cần nhớ: good -> better -> best, bad -> worse -> worst, far -> further -> furthest.
So sánh nhất luôn có mạo từ "the" đứng trước (the most expensive, the fastest).', '["Tính từ bất quy tắc cần nhớ: good -> better -> best, bad -> worse -> worst, far -> further -> furthest.","So sánh nhất luôn có mạo từ \"the\" đứng trước (the most expensive, the fastest)."]'::jsonb, '[{"target":"Tokyo is significantly more crowded than Kyoto.","vi":"Tokyo đông đúc hơn Kyoto một cách rõ rệt."}]'::jsonb, '[{"wrong":"This smartphone is more cheaper than that one.","correct":"This smartphone is cheaper than that one.","explanation":"\"Cheap\" là tính từ ngắn nên chỉ thêm đuôi -er thành \"cheaper\", không dùng đồng thời \"more\"."}]'::jsonb, 30, 2),
  ('en-a2-modals', 'en', 'A2', 'Động từ khuyết thiếu: Can, Could, Must, Should', 'Biểu thị khả năng, xin phép, lời khuyên và sự bắt buộc', 'Sau động từ khuyết thiếu (Modal verbs) luôn là một động từ nguyên mẫu không "to".', '{"pattern":"S + can / should / must + V-bare","tokens":[{"label":"Subject","role":"subject"},{"label":"can / should / must","role":"particle"},{"label":"V-nguyên mẫu không To","role":"verb"}]}'::jsonb, 'Can: chỉ khả năng ở hiện tại; Could: khả năng trong quá khứ hoặc lời đề nghị lịch sự.
Should: khuyên nhủ nên làm gì.
Must: bắt buộc phải làm theo quy định luật lệ.', '["Can: chỉ khả năng ở hiện tại; Could: khả năng trong quá khứ hoặc lời đề nghị lịch sự.","Should: khuyên nhủ nên làm gì.","Must: bắt buộc phải làm theo quy định luật lệ."]'::jsonb, '[{"target":"You should consult a doctor if the fever persists.","vi":"Bạn nên đi khám bác sĩ nếu cơn sốt vẫn kéo dài."}]'::jsonb, '[{"wrong":"He must to wear a safety helmet on site.","correct":"He must wear a safety helmet on site.","explanation":"Sau \"must\" là động từ nguyên mẫu không to (bare infinitive)."}]'::jsonb, 30, 3),
  ('en-a2-future-goingto', 'en', 'A2', 'Thì Tương lai gần: "Be going to" vs "Will"', 'Phân biệt kế hoạch dự định trước và quyết định nảy sinh tức thì', '"Be going to" dùng cho kế hoạch đã dự tính từ trước hoặc có bằng chứng thấy rõ.', '{"pattern":"S + am / is / are + going to + V-infinitive","tokens":[{"label":"Subject","role":"subject"},{"label":"am/is/are + going to","role":"verb"},{"label":"V-nguyên mẫu","role":"object"}]}'::jsonb, 'Dùng "be going to" khi có dấu hiệu nhìn thấy: "Look at those dark clouds! It is going to rain."
Dùng "will" cho quyết định bộc phát ngay lúc nói: "The phone is ringing. I will answer it."', '["Dùng \"be going to\" khi có dấu hiệu nhìn thấy: \"Look at those dark clouds! It is going to rain.\"","Dùng \"will\" cho quyết định bộc phát ngay lúc nói: \"The phone is ringing. I will answer it.\""]'::jsonb, '[{"target":"They are going to launch the new application next Monday.","vi":"Họ dự định sẽ phát hành ứng dụng mới vào thứ Hai tới."}]'::jsonb, '[{"wrong":"I am going to meeting him tomorrow.","correct":"I am going to meet him tomorrow.","explanation":"Sau \"be going to\" là động từ nguyên mẫu \"meet\", không dùng V-ing."}]'::jsonb, 30, 4),
  ('zh-hsk1-shi', 'zh', 'HSK 1', 'Câu phán đoán với chữ "是" (shì)', 'Cách dùng chữ 是 tương đương động từ "là" trong tiếng Việt', 'Dùng để nối chủ ngữ với danh từ biểu thị danh tính, nghề nghiệp hoặc quốc tịch.', '{"pattern":"Chủ ngữ + 是 + Danh từ bổ ngữ","tokens":[{"label":"主语 (S)","role":"subject"},{"label":"是 (shì)","role":"verb"},{"label":"名词 (Danh từ)","role":"object"}]}'::jsonb, 'Phủ định dùng "不是" (bù shì).
Không dùng "是" trước tính từ (Ví dụ: "Cô ấy rất đẹp" là 她很漂亮, không nói 她是漂亮).', '["Phủ định dùng \"不是\" (bù shì).","Không dùng \"是\" trước tính từ (Ví dụ: \"Cô ấy rất đẹp\" là 她很漂亮, không nói 她是漂亮)."]'::jsonb, '[{"target":"我是越南人，他是中国人。","vi":"Tôi là người Việt Nam, anh ấy là người Trung Quốc.","phonetic":"Wǒ shì Yuènán rén, tā shì Zhōngguó rén."}]'::jsonb, '[{"wrong":"今天天气是很好。","correct":"今天天气很好。","explanation":"Tính từ làm vị ngữ không cần dùng chữ \"是\", chỉ cần phó từ chỉ mức độ như \"很\"."}]'::jsonb, 30, 1),
  ('zh-hsk1-de', 'zh', 'HSK 1', 'Trợ từ kết cấu "的" (de)', 'Biểu thị quan hệ sở hữu và định ngữ bổ nghĩa cho danh từ', 'Đứng giữa định ngữ và trung tâm ngữ (A 的 B nghĩa là B của A).', '{"pattern":"Định ngữ + 的 + Trung tâm ngữ","tokens":[{"label":"Người sở hữu / Tính chất","role":"modifier"},{"label":"的 (de)","role":"particle"},{"label":"Danh từ chính","role":"object"}]}'::jsonb, 'Biểu thị sở hữu: 我的书 (Sách của tôi).
Quan hệ thân thuộc ruột thịt có thể lược bỏ 的: 我妈妈 (Mẹ tôi).', '["Biểu thị sở hữu: 我的书 (Sách của tôi).","Quan hệ thân thuộc ruột thịt có thể lược bỏ 的: 我妈妈 (Mẹ tôi)."]'::jsonb, '[{"target":"这是我朋友的新手机。","vi":"Đây là điện thoại mới của bạn tôi.","phonetic":"Zhè shì wǒ péngyou de xīn shǒujī."}]'::jsonb, '[{"wrong":"这是我书。","correct":"这是我的书。","explanation":"Quan hệ sở hữu đồ vật thông thường bắt buộc phải có trợ từ \"的\"."}]'::jsonb, 30, 2),
  ('zh-hsk1-ma', 'zh', 'HSK 1', 'Trợ từ nghi vấn "吗" (ma)', 'Biến câu trần thuật thành câu hỏi Có/Không', 'Đặt ở cuối câu khẳng định để tạo câu hỏi nghi vấn.', '{"pattern":"Câu khẳng định + 吗？","tokens":[{"label":"Câu hoàn chỉnh","role":"subject"},{"label":"吗 (ma)","role":"particle"}]}'::jsonb, 'Khi câu đã có đại từ nghi vấn (什么, 谁, 哪) thì không dùng "吗" nữa.', '["Khi câu đã có đại từ nghi vấn (什么, 谁, 哪) thì không dùng \"吗\" nữa."]'::jsonb, '[{"target":"你喜欢喝中国茶吗？","vi":"Bạn có thích uống trà Trung Quốc không?"}]'::jsonb, '[{"wrong":"他是谁吗？","correct":"他是谁？","explanation":"Đã có đại từ nghi vấn \"谁\" (ai) thì không dùng thêm \"吗\"."}]'::jsonb, 30, 3),
  ('zh-hsk1-zai', 'zh', 'HSK 1', 'Giới từ nơi chốn "在" (zài)', 'Biểu thị vị trí "ở / tại đâu đó"', 'Trong tiếng Hán, trạng ngữ chỉ nơi chốn (在 + Nơi chốn) luôn đứng trước động từ hành động.', '{"pattern":"Chủ ngữ + 在 + Nơi chốn + Động từ","tokens":[{"label":"Chủ ngữ","role":"subject"},{"label":"在 + Nơi chốn","role":"modifier"},{"label":"Động từ chính","role":"verb"}]}'::jsonb, 'Khác tiếng Việt: Ta nói "Tôi học ở thư viện", tiếng Trung nói "Tôi ở thư viện học" (我在图书馆学习).', '["Khác tiếng Việt: Ta nói \"Tôi học ở thư viện\", tiếng Trung nói \"Tôi ở thư viện học\" (我在图书馆学习)."]'::jsonb, '[{"target":"我们在家吃晚饭。","vi":"Chúng tôi ăn cơm tối ở nhà."}]'::jsonb, '[{"wrong":"我看书在图书馆。","correct":"我在图书馆看书。","explanation":"Trạng ngữ nơi chốn bắt buộc phải đặt trước động từ."}]'::jsonb, 30, 4),
  ('zh-hsk2-bi', 'zh', 'HSK 2', 'Câu so sánh chữ "比" (bǐ)', 'Cấu trúc so sánh hơn giữa hai sự vật', 'A 比 B + Tính từ (A hơn B về mặt nào đó).', '{"pattern":"A + 比 + B + Tính từ (+ 一点儿 / 得多)","tokens":[{"label":"A","role":"subject"},{"label":"比 (bǐ)","role":"particle"},{"label":"B","role":"object"},{"label":"Tính từ","role":"verb"}]}'::jsonb, 'Không dùng phó từ "很", "非常" trong câu chữ 比.', '["Không dùng phó từ \"很\", \"非常\" trong câu chữ 比."]'::jsonb, '[{"target":"今天比昨天冷得多。","vi":"Hôm nay lạnh hơn hôm qua rất nhiều."}]'::jsonb, '[{"wrong":"他比我很高。","correct":"他比我高。","explanation":"Trong câu chữ 比 không được dùng chữ \"很\"."}]'::jsonb, 30, 1),
  ('zh-hsk2-le', 'zh', 'HSK 2', 'Trợ từ ngữ khí "了" (le)', 'Biểu thị sự hoàn thành của động tác hoặc sự thay đổi trạng thái', 'Đứng sau động từ hoặc ở cuối câu để báo hiệu trạng thái mới xuất hiện.', '{"pattern":"S + V + 了 + O","tokens":[{"label":"S","role":"subject"},{"label":"V + 了","role":"verb"}]}'::jsonb, 'Phủ định không dùng "不" mà dùng "没/没有 + V" (khi đó bỏ 了).', '["Phủ định không dùng \"不\" mà dùng \"没/没有 + V\" (khi đó bỏ 了)."]'::jsonb, '[{"target":"我吃过早饭了。","vi":"Tôi đã ăn sáng xong rồi."}]'::jsonb, '[{"wrong":"我没买了这本书。","correct":"我没买这本书。","explanation":"Khi đã dùng \"没\" thì không dùng \"了\" nữa."}]'::jsonb, 30, 2),
  ('zh-hsk2-guò', 'zh', 'HSK 2', 'Trợ từ động thái "过" (guo)', 'Diễn tả trải nghiệm từng làm điều gì trong đời', 'V + 过 = đã từng làm gì đó trong quá khứ.', '{"pattern":"S + V + 过 + O","tokens":[{"label":"S","role":"subject"},{"label":"V + 过","role":"verb"}]}'::jsonb, 'Nhấn mạnh vào kinh nghiệm, trải nghiệm bản thân.', '["Nhấn mạnh vào kinh nghiệm, trải nghiệm bản thân."]'::jsonb, '[{"target":"我去过两次北京。","vi":"Tôi đã từng đi Bắc Kinh hai lần."}]'::jsonb, '[{"wrong":"我没去北京过。","correct":"我没去过北京。","explanation":"Trợ từ \"过\" phải gắn liền ngay sau động từ."}]'::jsonb, 30, 3),
  ('zh-hsk2-jiu-cai', 'zh', 'HSK 2', 'Phân biệt "就" (jiù) và "才" (cái)', 'Diễn tả hành động diễn ra sớm/nhanh (就) hay muộn/chậm (才)', '就 nhấn mạnh tính thuận lợi, nhanh chóng; 才 biểu thị sự chậm trễ, khó khăn mới đạt được.', '{"pattern":"Thời gian + 就 / 才 + Động từ","tokens":[{"label":"Thời gian","role":"modifier"},{"label":"就 / 才","role":"particle"},{"label":"V","role":"verb"}]}'::jsonb, 'Sau "才" cuối câu không dùng "了".', '["Sau \"才\" cuối câu không dùng \"了\"."]'::jsonb, '[{"target":"他八点就到了，我九点才来。","vi":"Anh ấy 8 giờ đã đến rồi, còn tôi 9 giờ mới tới."}]'::jsonb, '[{"wrong":"他昨天十点才睡了。","correct":"他昨天十点才睡。","explanation":"Sau \"才\" không dùng trợ từ \"了\"."}]'::jsonb, 30, 4),
  ('ja-n5-particles-wa-ga', 'ja', 'N5', 'Phân biệt Trợ từ は (Wa) và が (Ga)', 'Chủ đề câu (は) đối lập với chủ ngữ nhấn mạnh (が)', 'は nêu lên chủ đề của câu, còn が nhấn mạnh chính đối tượng đứng trước nó.', '{"pattern":"A は B です / A が V-ます","tokens":[{"label":"Danh từ","role":"subject"},{"label":"は / が","role":"particle"},{"label":"Vị ngữ","role":"verb"}]}'::jsonb, 'Trong câu có từ để hỏi (誰, 何) làm chủ ngữ, bắt buộc dùng が: 誰が来ましたか？', '["Trong câu có từ để hỏi (誰, 何) làm chủ ngữ, bắt buộc dùng が: 誰が来ましたか？"]'::jsonb, '[{"target":"私は学生です。田中さんが先生です。","vi":"Tôi là học sinh. Anh Tanaka là giáo viên."}]'::jsonb, '[{"wrong":"誰は来ましたか？","correct":"誰が来ましたか？","explanation":"Từ để hỏi đứng đầu làm chủ ngữ bắt buộc đi với が."}]'::jsonb, 30, 1),
  ('ja-n5-te-form', 'ja', 'N5', 'Thể Te (〜てください / 〜ています)', 'Chia thể Te để nhờ vả lịch sự hoặc diễn tả hành động đang diễn ra', 'Thể Te là thể biến đổi quan trọng bậc nhất của động từ tiếng Nhật.', '{"pattern":"V-て + ください / います","tokens":[{"label":"V-て","role":"verb"},{"label":"ください / います","role":"particle"}]}'::jsonb, 'Nhóm 1: chia theo vần đuôi (ku -> ite, su -> shite, mu/bu/nu -> nde).', '["Nhóm 1: chia theo vần đuôi (ku -> ite, su -> shite, mu/bu/nu -> nde)."]'::jsonb, '[{"target":"ちょっと待ってください。","vi":"Xin vui lòng đợi một chút."}]'::jsonb, '[{"wrong":"待ってをください。","correct":"待ってください。","explanation":"Sau thể Te không chèn thêm trợ từ を."}]'::jsonb, 30, 2),
  ('ja-n5-ni-de', 'ja', 'N5', 'Trợ từ chỉ nơi chốn: に (Ni) vs で (De)', 'Nơi tồn tại (に) và Nơi diễn ra hành động (で)', 'Dùng に với động từ tồn tại (いる, ある); dùng で với động từ hành động (食べる, 勉強する).', '{"pattern":"Nơi chốn + に (Tồn tại) / で (Hành động)","tokens":[{"label":"Địa điểm","role":"modifier"},{"label":"に / で","role":"particle"}]}'::jsonb, 'Ví dụ: 図書館で本を読む (Hành động) vs 図書館に本がある (Tồn tại).', '["Ví dụ: 図書館で本を読む (Hành động) vs 図書館に本がある (Tồn tại)."]'::jsonb, '[{"target":"公園で散歩をします。","vi":"Tôi đi dạo ở công viên."}]'::jsonb, '[{"wrong":"部屋で猫がいます。","correct":"部屋に猫がいます。","explanation":"Động từ tồn tại \"います\" bắt buộc đi với に."}]'::jsonb, 30, 3),
  ('ja-n5-adjectives', 'ja', 'N5', 'Tính từ đuôi い (I) và đuôi な (Na)', 'Quy tắc chia phủ định và quá khứ của 2 nhóm tính từ', 'Tính từ đuôi い: bỏ い thêm くない / かった; tính từ đuôi な thêm じゃない / でした.', '{"pattern":"Adj-i -> くない / Adj-na -> じゃない","tokens":[{"label":"Tính từ","role":"verb"}]}'::jsonb, 'Lưu ý tính từ bất quy tắc いい (tốt) -> よくない, よかった.', '["Lưu ý tính từ bất quy tắc いい (tốt) -> よくない, よかった."]'::jsonb, '[{"target":"昨日はあまり寒くなかったです。","vi":"Hôm qua trời không lạnh lắm."}]'::jsonb, '[{"wrong":"昨日は寒くないでした。","correct":"昨日は寒くなかったです。","explanation":"Quá khứ tính từ đuôi i phải đổi thành かった."}]'::jsonb, 30, 4),
  ('ja-n4-potential', 'ja', 'N4', 'Thể Khả năng (可能形 - Kanoukei)', 'Diễn tả năng lực có thể làm được việc gì', 'Nhóm 1: cột u -> e + る; Nhóm 2: bỏ る + られる; Nhóm 3: できる, こられる.', '{"pattern":"N + が + V-khả năng","tokens":[{"label":"Tân ngữ","role":"object"},{"label":"が","role":"particle"},{"label":"V-khả năng","role":"verb"}]}'::jsonb, 'Trong thể khả năng, trợ từ を thường chuyển thành が: 日本語が話せる.', '["Trong thể khả năng, trợ từ を thường chuyển thành が: 日本語が話せる."]'::jsonb, '[{"target":"私は漢字が少し読めます。","vi":"Tôi có thể đọc được một chút chữ Hán."}]'::jsonb, '[{"wrong":"漢字を読めます。","correct":"漢字が読めます。","explanation":"Tân ngữ của thể khả năng ưu tiên dùng trợ từ が."}]'::jsonb, 30, 1),
  ('ja-n4-tara', 'ja', 'N4', 'Thể Điều kiện 〜たら (Tara)', 'Cấu trúc "Nếu... thì..." hoặc "Sau khi làm A thì làm B"', 'Động từ chia thể Quá khứ Ta + ら (V-た + ら).', '{"pattern":"V-たら + Kết quả","tokens":[{"label":"V-たら","role":"modifier"},{"label":"Mệnh đề sau","role":"verb"}]}'::jsonb, 'Có tính ứng dụng rộng nhất trong các mẫu câu điều kiện tiếng Nhật.', '["Có tính ứng dụng rộng nhất trong các mẫu câu điều kiện tiếng Nhật."]'::jsonb, '[{"target":"時間があったら、映画を見に行きましょう。","vi":"Nếu có thời gian thì chúng ta cùng đi xem phim nhé."}]'::jsonb, '[{"wrong":"時間があるたら、行きます。","correct":"時間があったら、行きます。","explanation":"Phải chia về thể Ta rồi mới thêm ら (あったら)."}]'::jsonb, 30, 2),
  ('ja-n4-passive', 'ja', 'N4', 'Thể Bị động (受身形 - Ukemi)', 'Chủ ngữ bị/được tác động bởi người khác', 'Nhóm 1: cột a + れる; Nhóm 2: られる; Nhóm 3: される, こられる.', '{"pattern":"Chủ ngữ + は + Tác nhân + に + V-bị động","tokens":[{"label":"Chủ ngữ","role":"subject"},{"label":"Tác nhân + に","role":"object"},{"label":"V-bị động","role":"verb"}]}'::jsonb, 'Bị động phiền toái (Meiwaku ukemi): 雨に降られた (Bị dính mưa phiền toái).', '["Bị động phiền toái (Meiwaku ukemi): 雨に降られた (Bị dính mưa phiền toái)."]'::jsonb, '[{"target":"先生に名前を呼ばれました。","vi":"Tôi đã được giáo viên gọi tên."}]'::jsonb, '[{"wrong":"先生を呼ばれました。","correct":"先生に呼ばれました。","explanation":"Tác nhân gây tác động đi với trợ từ に."}]'::jsonb, 30, 3),
  ('ja-n4-causative', 'ja', 'N4', 'Thể Sai khiến (使役形 - Shieki)', 'Cho phép hoặc bắt buộc ai đó làm việc gì', 'Nhóm 1: cột a + せる; Nhóm 2: させる; Nhóm 3: させる, こさせる.', '{"pattern":"A は B に + V-sai khiến","tokens":[{"label":"Người ra lệnh","role":"subject"},{"label":"Người nhận lệnh + に","role":"object"},{"label":"V-sai khiến","role":"verb"}]}'::jsonb, '〜させてください dùng để xin phép cho bản thân mình được làm gì một cách lịch thiệp.', '["〜させてください dùng để xin phép cho bản thân mình được làm gì một cách lịch thiệp."]'::jsonb, '[{"target":"私にその仕事をやらせてください。","vi":"Xin hãy cho phép tôi được làm công việc đó."}]'::jsonb, '[{"wrong":"私をやらせてください。","correct":"私にやらせてください。","explanation":"Đối tượng được cho phép nhận trợ từ に."}]'::jsonb, 30, 4)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, level = EXCLUDED.level, explanation = EXCLUDED.explanation, explanation_notes = EXCLUDED.explanation_notes, examples = EXCLUDED.examples, common_mistakes = EXCLUDED.common_mistakes;

INSERT INTO public.grammar_exercises (id, point_id, question_type, prompt, question, options, correct_index, correct_answer, correct_order, scrambled_words, hint, explanation, sort_order) VALUES

  ('ex-a1-1-1', 'en-a1-tobe', 'multiple_choice', 'Chọn dạng đúng của to be:', 'My brother and I _____ big fans of science fiction movies.', '["am","is","are","be"]'::jsonb, 2, 'are', '[]'::jsonb, '[]'::jsonb, NULL, '"My brother and I" tương đương với đại từ "We" (chúng tôi - số nhiều), do đó dùng "are".', 1),
  ('ex-a1-1-2', 'en-a1-tobe', 'fill_blank', 'Điền dạng đúng của động từ to be (phủ định ngắn gọn):', 'He _____ (not be) ready for the final exam yet.', '[]'::jsonb, NULL, 'isn''t', '[]'::jsonb, '[]'::jsonb, 'Viết dạng viết tắt isn''t', 'Ngôi "He" đi với "is not", dạng viết tắt là "isn''t".', 2),
  ('ex-a1-1-3', 'en-a1-tobe', 'word_order', 'Sắp xếp các từ sau thành câu hoàn chỉnh:', 'very / the weather / pleasant / today / is', '[]'::jsonb, NULL, 'The weather is very pleasant today', '["The weather","is","very","pleasant","today"]'::jsonb, '["pleasant","today","is","The weather","very"]'::jsonb, NULL, 'Trật tự câu: Chủ ngữ (The weather) + Động từ (is) + Trạng từ + Tính từ (very pleasant) + Thời gian (today).', 3),
  ('ex-a1-2-1', 'en-a1-present-simple', 'multiple_choice', 'Chọn đáp án đúng:', 'Water _____ at 100 degrees Celsius under standard atmospheric pressure.', '["boil","boils","is boiling","boiled"]'::jsonb, 1, 'boils', '[]'::jsonb, '[]'::jsonb, NULL, 'Sự thật hiển nhiên/chân lý khoa học dùng thì hiện tại đơn, "Water" là danh từ không đếm được nên chia "boils".', 1),
  ('ex-a1-2-2', 'en-a1-present-simple', 'word_order', 'Sắp xếp các từ thành câu đúng:', 'breakfast / always / at seven / eats / David', '[]'::jsonb, NULL, 'David always eats breakfast at seven', '["David","always","eats","breakfast","at seven"]'::jsonb, '["always","eats","David","breakfast","at seven"]'::jsonb, NULL, 'Trạng từ tần suất "always" đứng trước động từ thường "eats".', 2),
  ('ex-a1-3-1', 'en-a1-articles', 'multiple_choice', 'Điền mạo từ thích hợp:', 'It took us almost _____ hour to reach the train station.', '["a","an","the","no article"]'::jsonb, 1, 'an', '[]'::jsonb, '[]'::jsonb, NULL, '"Hour" có âm "h" câm, phát âm bắt đầu bằng nguyên âm /ˈaʊər/ nên dùng "an".', 1),
  ('ex-a1-4-1', 'en-a1-pronouns', 'fill_blank', 'Điền tính từ sở hữu thích hợp (của họ):', 'The students forgot to bring _____ textbooks to class.', '[]'::jsonb, NULL, 'their', '[]'::jsonb, '[]'::jsonb, 'Tính từ sở hữu của They', 'Tính từ sở hữu tương ứng với "The students" (They) là "their".', 1),
  ('ex-a2-1-1', 'en-a2-past-simple', 'multiple_choice', 'Chọn đáp án đúng:', 'Alexander Fleming _____ penicillin by accident in 1928.', '["discover","discovered","has discovered","discovering"]'::jsonb, 1, 'discovered', '[]'::jsonb, '[]'::jsonb, NULL, 'Sự kiện lịch sử có mốc năm xác định trong quá khứ (in 1928) bắt buộc chia quá khứ đơn "discovered".', 1),
  ('ex-a2-1-2', 'en-a2-past-simple', 'word_order', 'Sắp xếp các từ thành câu đúng:', 'yesterday / finish / she / her homework / did not', '[]'::jsonb, NULL, 'She did not finish her homework yesterday', '["She","did not","finish","her homework","yesterday"]'::jsonb, '["did not","her homework","finish","She","yesterday"]'::jsonb, NULL, 'Cấu trúc S + did not + V + O + Time.', 2),
  ('ex-a2-2-1', 'en-a2-comparatives', 'fill_blank', 'Điền dạng so sánh hơn của tính từ "good":', 'Today the weather is much _____ than it was yesterday.', '[]'::jsonb, NULL, 'better', '[]'::jsonb, '[]'::jsonb, 'Bất quy tắc của good', 'So sánh hơn của "good" là "better".', 1),
  ('ex-a2-3-1', 'en-a2-modals', 'multiple_choice', 'Chọn đáp án thích hợp:', 'It is raining cats and dogs. You _____ take an umbrella.', '["should","should to","must to","can to"]'::jsonb, 0, 'should', '[]'::jsonb, '[]'::jsonb, NULL, 'Đưa ra lời khuyên hợp lý và theo sau là V-bare nên dùng "should".', 1),
  ('ex-a2-4-1', 'en-a2-future-goingto', 'word_order', 'Sắp xếp các từ thành câu đúng:', 'visit / to / are / going / grandparents / we / our', '[]'::jsonb, NULL, 'We are going to visit our grandparents', '["We","are","going","to","visit","our","grandparents"]'::jsonb, '["our","visit","are","going","We","grandparents","to"]'::jsonb, NULL, 'Cấu trúc S + are going to + V + O.', 1),
  ('ex-zh-1-1', 'zh-hsk1-shi', 'multiple_choice', 'Chọn từ thích hợp điền vào chỗ trống:', '李老师 _____ 我们学校的汉语老师。', '["很","在","是","有"]'::jsonb, 2, '是', '[]'::jsonb, '[]'::jsonb, NULL, 'Câu biểu thị nghề nghiệp/danh tính dùng "是".', 1),
  ('ex-zh-1-2', 'zh-hsk1-de', 'word_order', 'Sắp xếp các từ thành câu đúng:', '汉语词典 / 的 / 这 / 是 / 我', '[]'::jsonb, NULL, '这 是 我 的 汉语词典', '["这","是","我","的","汉语词典"]'::jsonb, '["汉语词典","我","的","这","是"]'::jsonb, NULL, 'Trật tự: 这是 (Đây là) + 我的 (của tôi) + 汉语词典 (từ điển tiếng Hán).', 1),
  ('ex-zh-1-3', 'zh-hsk1-ma', 'multiple_choice', 'Chọn từ thích hợp:', '你明天去学校 _____ ？', '["呢","吧","吗","的"]'::jsonb, 2, '吗', '[]'::jsonb, '[]'::jsonb, NULL, 'Câu hỏi có/không đặt "吗" ở cuối.', 1),
  ('ex-zh-1-4', 'zh-hsk1-zai', 'word_order', 'Sắp xếp thành câu đúng:', '在 / 他 / 公司 / 工作', '[]'::jsonb, NULL, '他 在 公司 工作', '["他","在","公司","工作"]'::jsonb, '["工作","他","在","公司"]'::jsonb, NULL, 'Cấu trúc Chủ ngữ + 在 Nơi chốn + Động từ.', 1),
  ('ex-zh-2-1', 'zh-hsk2-bi', 'multiple_choice', 'Chọn đáp án đúng:', '妹妹 _____ 姐姐更喜欢听音乐。', '["跟","比","对","在"]'::jsonb, 1, '比', '[]'::jsonb, '[]'::jsonb, NULL, 'Câu so sánh dùng "比".', 1),
  ('ex-zh-2-2', 'zh-hsk2-le', 'fill_blank', 'Điền từ phủ định quá khứ:', '他昨天 _____ 来上课。', '[]'::jsonb, NULL, '没', '[]'::jsonb, '[]'::jsonb, 'Phủ định của đã làm', 'Hành động chưa diễn ra trong quá khứ dùng "没".', 1),
  ('ex-zh-2-3', 'zh-hsk2-guò', 'multiple_choice', 'Chọn đáp án đúng:', '你吃 _____ 烤鸭吗？', '["了","过","着","得"]'::jsonb, 1, '过', '[]'::jsonb, '[]'::jsonb, NULL, 'Hỏi kinh nghiệm đã từng ăn chưa dùng "过".', 1),
  ('ex-zh-2-4', 'zh-hsk2-jiu-cai', 'multiple_choice', 'Chọn từ đúng:', '作业太难了，我花了一个晚上 _____ 做完。', '["就","才","也","还"]'::jsonb, 1, '才', '[]'::jsonb, '[]'::jsonb, NULL, 'Nhấn mạnh sự khó khăn, mất nhiều thời gian dùng "才".', 1),
  ('ex-ja-1-1', 'ja-n5-particles-wa-ga', 'multiple_choice', 'Chọn trợ từ thích hợp:', 'どれ _____ あなたの傘ですか。', '["は","が","を","に"]'::jsonb, 1, 'が', '[]'::jsonb, '[]'::jsonb, NULL, 'Từ để hỏi "どれ" đi với trợ từ が.', 1),
  ('ex-ja-1-2', 'ja-n5-te-form', 'fill_blank', 'Chia động từ 読む (đọc) sang thể Te:', '本を _____ ください。', '[]'::jsonb, NULL, '読んで', '[]'::jsonb, '[]'::jsonb, 'đuôi mu biến thành nde', 'Nhóm 1 đuôi む chuyển thành んで: 読んで.', 1),
  ('ex-ja-1-3', 'ja-n5-ni-de', 'multiple_choice', 'Chọn trợ từ đúng:', '机の上 _____ ノートがあります。', '["で","に","を","へ"]'::jsonb, 1, 'に', '[]'::jsonb, '[]'::jsonb, NULL, 'Chỉ nơi tồn tại của đồ vật (ある) dùng に.', 1),
  ('ex-ja-1-4', 'ja-n5-adjectives', 'multiple_choice', 'Chọn dạng đúng:', 'この部屋はとても _____ です。', '["静かな","静か","静かに","静かだ"]'::jsonb, 1, '静か', '[]'::jsonb, '[]'::jsonb, NULL, 'Tính từ đuôi na đứng trước です thì bỏ な.', 1),
  ('ex-ja-2-1', 'ja-n4-potential', 'multiple_choice', 'Chọn dạng khả năng:', '一人で病院へ _____ か。', '["行けます","行きます","行かれます","行かせます"]'::jsonb, 0, '行けます', '[]'::jsonb, '[]'::jsonb, NULL, 'Động từ 行く nhóm 1 chuyển cột e thành 行ける -> 行けます.', 1),
  ('ex-ja-2-2', 'ja-n4-tara', 'fill_blank', 'Chia điều kiện tara của 降る (mưa rơi):', '雨が _____ 、試合は中止です。', '[]'::jsonb, NULL, '降ったら', '[]'::jsonb, '[]'::jsonb, 'đuôi ru chia ta thành futta', '降る -> 降った -> 降ったら.', 1),
  ('ex-ja-2-3', 'ja-n4-passive', 'multiple_choice', 'Chọn trợ từ thích hợp:', '妹は母 _____ 叱られました。', '["に","を","で","から"]'::jsonb, 0, 'に', '[]'::jsonb, '[]'::jsonb, NULL, 'Người mắng (tác nhân) đi với trợ từ に.', 1),
  ('ex-ja-2-4', 'ja-n4-causative', 'multiple_choice', 'Chọn dạng đúng:', '母は子どもに野菜を _____ 。', '["食べさせました","食べられました","食べました","食べたがりました"]'::jsonb, 0, '食べさせました', '[]'::jsonb, '[]'::jsonb, NULL, 'Mẹ bắt con ăn rau (sai khiến) dùng 食べさせました.', 1)
ON CONFLICT (id) DO UPDATE SET prompt = EXCLUDED.prompt, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, correct_answer = EXCLUDED.correct_answer, correct_order = EXCLUDED.correct_order, scrambled_words = EXCLUDED.scrambled_words, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation;

-- 9. BÀI HỌC MEDIA VIDEO / PODCAST (Kỳ vọng: 4 bài học, 15 cues, 3 câu quiz)
INSERT INTO public.media_items (id, media_type, language, level, topic, title, vietnamese_title, speaker, provider, source_url, duration_seconds, is_published) VALUES

  ('media-en-ted-memory', 'video', 'en', 'B1 - B2', 'tech', 'How Memories Form and How We Lose Them', 'Ký ức được hình thành và mất đi như thế nào trong não bộ', 'TED-Ed • Catharine Young', 'youtube', 'https://www.youtube.com/watch?v=sample', 154, true),
  ('media-en-bbc-habit', 'podcast', 'en', 'B1 - B2', 'life', '6 Minute English: Breaking Bad Habits', 'Bản tin 6 phút tiếng Anh: Cách từ bỏ những thói quen xấu', 'BBC Learning English', 'youtube', 'https://www.youtube.com/watch?v=sample', 180, true),
  ('media-zh-tea-culture', 'video', 'zh', 'HSK 3 - 4', 'culture', '中国传统茶艺与慢生活哲学', 'Nghệ thuật trà đạo truyền thống Trung Hoa và triết lý sống an nhiên', 'CCTV 纪录片', 'youtube', 'https://www.youtube.com/watch?v=sample', 160, true),
  ('media-ja-daily-routine', 'video', 'ja', 'JLPT N4 - N3', 'life', '日本の朝のルーティンと自然な挨拶', 'Thói quen buổi sáng tại Nhật Bản và cách chào hỏi tự nhiên', 'Nihongo no Mori Channel', 'youtube', 'https://www.youtube.com/watch?v=sample', 150, true)
