INSERT INTO public.media_cues (id, media_id, subtitle_lang, start_ms, end_ms, text, translation_vi, vocab_hints, sort_order) VALUES

  ('1a23ed89-89be-56c1-9435-9ce248c4274a', 'media-en-ted-memory', 'en', 0, 8000, 'Imagine your brain as a vast library filled with millions of complex memories.', 'Hãy tưởng tượng bộ não của bạn như một thư viện khổng lồ chứa hàng triệu ký ức phức tạp.', '[{"word":"vast","meaning":"Bao la, rộng lớn khổng lồ"},{"word":"complex","meaning":"Phức tạp, nhiều tầng lớp"}]'::jsonb, 1),
  ('e15fef72-ee7b-55c1-8560-8305630032cb', 'media-en-ted-memory', 'en', 8000, 17000, 'Memories are encoded by networks of neurons firing in specific synchronous patterns.', 'Ký ức được mã hoá bởi các mạng lưới tế bào thần kinh kích hoạt theo những mô thức đồng bộ cụ thể.', '[{"word":"encoded","meaning":"Được mã hoá, lưu trữ"},{"word":"synchronous","meaning":"Đồng bộ, cùng lúc"}]'::jsonb, 2),
  ('10723890-a639-553b-a3ee-528e0a179d3b', 'media-en-ted-memory', 'en', 17000, 27000, 'Short-term memory holds information temporarily, like a scratchpad for immediate calculations.', 'Trí nhớ ngắn hạn lưu giữ thông tin tạm thời, tựa như một cuốn sổ nháp cho những phép tính tức thì.', '[{"word":"temporarily","meaning":"Tạm thời, ngắn hạn"},{"word":"scratchpad","meaning":"Sổ nháp ghi nhanh"}]'::jsonb, 3),
  ('457b827a-ee1e-5902-89d9-e7e14cbbd450', 'media-en-ted-memory', 'en', 27000, 38000, 'To convert this into long-term memory, the brain undergoes a biochemical process called consolidation.', 'Để chuyển đổi điều này thành trí nhớ dài hạn, não bộ trải qua một quá trình sinh hoá gọi là sự củng cố ký ức.', '[{"word":"consolidation","meaning":"Sự củng cố, làm bền vững"},{"word":"undergoes","meaning":"Trải qua, chịu sự biến đổi"}]'::jsonb, 4),
  ('619fbcc4-0465-57d2-aaff-9746e2f3211b', 'media-en-ted-memory', 'en', 38000, 50000, 'During sleep, the hippocampus replays these events to strengthen the synaptic connections.', 'Trong giấc ngủ, hồi hải mã tái phát lại các sự kiện này nhằm củng cố các liên kết synap thần kinh.', '[{"word":"hippocampus","meaning":"Hồi hải mã (vùng não lưu giữ ký ức)"},{"word":"strengthen","meaning":"Làm mạnh thêm, củng cố"}]'::jsonb, 5),
  ('a13f1638-c764-55dd-bb85-c9d6f931ea4d', 'media-en-bbc-habit', 'en', 0, 9000, 'Hello and welcome to 6 Minute English from BBC Learning English. I am Neil.', 'Xin chào và chào mừng bạn đến với 6 Minute English của BBC Learning English. Tôi là Neil.', '[]'::jsonb, 1),
  ('80924df7-5934-5d4c-9e10-1ceb099582fc', 'media-en-bbc-habit', 'en', 9000, 19000, 'And I am Sam. Today we are talking about habits, particularly those annoying habits we want to kick.', 'Và tôi là Sam. Hôm nay chúng ta sẽ thảo luận về thói quen, đặc biệt là những thói quen phiền toái mà ta muốn từ bỏ.', '[{"word":"annoying","meaning":"Gây phiền toái, bực mình"},{"word":"kick","meaning":"Từ bỏ, dứt bỏ (thói quen xấu)"}]'::jsonb, 2),
  ('6ad492f8-c428-5977-8b54-aedc1f2c00bd', 'media-en-bbc-habit', 'en', 19000, 32000, 'Psychologists suggest that habits form a neurological loop: cue, routine, and reward.', 'Các nhà tâm lý học chỉ ra rằng thói quen hình thành một vòng lặp thần kinh: gợi ý, hành vi và phần thưởng.', '[{"word":"neurological loop","meaning":"Vòng lặp dẫn truyền thần kinh"},{"word":"cue","meaning":"Tín hiệu gợi nhắc, kích hoạt"}]'::jsonb, 3),
  ('3433057d-264c-5ffc-9cdf-3edbd8ba6187', 'media-en-bbc-habit', 'en', 32000, 45000, 'To replace an unhealthy routine, you must first identify the underlying trigger.', 'Để thay thế một hành vi không lành mạnh, trước tiên bạn phải xác định được tác nhân kích hoạt ẩn sâu bên dưới.', '[{"word":"replace","meaning":"Thay thế, hoán đổi"},{"word":"trigger","meaning":"Tác nhân kích hoạt phản xạ"}]'::jsonb, 4),
  ('1ea77234-c976-526c-a758-4e057478a401', 'media-zh-tea-culture', 'zh', 0, 8000, '茶在中国不仅是一种日常饮品，更是千年文化的传承。', 'Trà ở Trung Quốc không chỉ là thức uống thường ngày, mà còn là sự kế thừa văn hoá ngàn năm.', '[{"word":"饮品","meaning":"Đồ uống, thức uống"},{"word":"传承","meaning":"Kế thừa, lưu truyền"}]'::jsonb, 1),
  ('e5f6b31c-ff1c-5673-8f68-3a649e85f976', 'media-zh-tea-culture', 'zh', 8000, 18000, '泡好一壶清茶，需要心平气和与恰到好处的水温。', 'Pha được một ấm trà ngon cần sự tâm bình khí hoà và nhiệt độ nước vừa vặn.', '[{"word":"心平气和","meaning":"Tâm bình khí hoà, điềm tĩnh"},{"word":"水温","meaning":"Nhiệt độ của nước"}]'::jsonb, 2),
  ('624fc71b-45ea-5b77-b19e-105e8b3c8d12', 'media-zh-tea-culture', 'zh', 18000, 30000, '品茶的过程教会人们在快节奏的生活中停下脚步，感受宁静。', 'Quá trình thưởng trà dạy con người dừng bước giữa nhịp sống hối hả để cảm nhận sự tĩnh lặng.', '[{"word":"快节奏","meaning":"Nhịp sống nhanh, hối hả"},{"word":"宁静","meaning":"Tĩnh lặng, an yên"}]'::jsonb, 3),
  ('7a9e9e6a-1db6-5103-b088-d30dda56aa38', 'media-ja-daily-routine', 'ja', 0, 8000, '皆さん、おはようございます！今日も清々しい朝ですね。', 'Chào buổi sáng mọi người! Hôm nay quả là một buổi sáng trong lành sảng khoái.', '[{"word":"清々しい","meaning":"Trong lành, tươi mát sảng khoái"}]'::jsonb, 1),
  ('16348247-0bd4-5101-a58c-dd29393c1ba9', 'media-ja-daily-routine', 'ja', 8000, 18000, '朝起きたら、まずコップ一杯の白湯を飲むのが私のルーティンです。', 'Sau khi thức dậy vào buổi sáng, thói quen của tôi là uống một cốc nước ấm trước tiên.', '[{"word":"白湯","meaning":"Nước ấm đun sôi để nguội"},{"word":"ルーティン","meaning":"Thói quen định kỳ hàng ngày"}]'::jsonb, 2),
  ('8fb8e50f-c79c-5c50-894d-5f4dacaebfb9', 'media-ja-daily-routine', 'ja', 18000, 30000, '近所の人に笑顔で「いってきます」と声をかけると、気持ちよく一日が始まります。', 'Khi mỉm cười chào "Tôi đi đây nhé" với hàng xóm, ngày mới sẽ bắt đầu thật dễ chịu.', '[{"word":"近所","meaning":"Hàng xóm láng giềng gần nhà"}]'::jsonb, 3)
ON CONFLICT (id) DO UPDATE SET text = EXCLUDED.text, translation_vi = EXCLUDED.translation_vi, vocab_hints = EXCLUDED.vocab_hints;

INSERT INTO public.media_quiz_questions (id, media_id, segment_time_sec, question, options, correct_index, explanation) VALUES

  ('6c3dbdd7-4019-55c7-bab0-d35cc346bf80', 'media-en-ted-memory', 8, 'Ký ức được mã hoá trong não bộ nhờ cơ chế nào?', '["Nhờ sự lưu trữ tĩnh của các tế bào mỡ","Mạng lưới neuron kích hoạt theo mô thức đồng bộ","Thông qua việc ghi chép trực tiếp vào võng mạc","Não bộ không tự mã hoá mà phụ thuộc vào âm thanh"]'::jsonb, 1, 'Đoạn thoại nêu rõ: "Memories are encoded by networks of neurons firing in specific synchronous patterns".'),
  ('6f58de99-e197-5d32-9589-c2521f069b4d', 'media-en-ted-memory', 38, 'Não bộ củng cố ký ức dài hạn chủ yếu vào thời điểm nào?', '["Khi đang tập thể dục thể thao cường độ cao","Trong giấc ngủ nhờ hoạt động của vùng hồi hải mã","Ngay lập tức sau khi uống cà phê","Vào buổi sáng sớm trước khi ăn sáng"]'::jsonb, 1, 'Đoạn thoại chỉ ra: "During sleep, the hippocampus replays these events to strengthen synaptic connections".'),
  ('e8758b80-06e5-57b5-87f8-c2b14c27339b', 'media-en-bbc-habit', 19, 'Vòng lặp thói quen thần kinh bao gồm 3 yếu tố nào?', '["Mục tiêu, Kế hoạch và Thành công","Tín hiệu (Cue), Hành vi (Routine) và Phần thưởng (Reward)","Suy nghĩ, Cảm xúc và Hành động","Bắt đầu, Thử thách và Kết thúc"]'::jsonb, 1, 'Bài nói chỉ rõ: "habits form a neurological loop: cue, routine, and reward".')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;

