INSERT INTO public.reading_sections (id, reading_id, sort_order, original_text, translated_text, vocab_notes) VALUES

  ('afe3cd1d-f3fe-5b88-87a9-287888b0c991', 'read-en-tortoise-hare', 1, 'A Hare was once ridiculing the slow feet of a Tortoise. The Tortoise, smiling quietly, replied that despite his heavy shell, he could beat the nimble Hare in a race across the countryside.', 'Một ngày nọ, chú Thỏ buông lời chế giễu đôi chân chậm chạp của Rùa. Rùa chỉ mỉm cười điềm tĩnh đáp lại rằng bất chấp chiếc mai nặng nề, chú vẫn có thể đánh bại chú Thỏ lanh lợi trong một cuộc đua xuyên qua cánh đồng.', '[{"word":"ridiculing","meaning":"Chế giễu, nhạo báng"},{"word":"nimble","meaning":"Nhanh nhẹn, lanh lẹ"}]'::jsonb),
  ('f000a13a-bfb2-5732-80ba-54bdfa14b390', 'read-en-tortoise-hare', 2, 'The Hare, overly confident in his natural swiftness, accepted the challenge without hesitation. Soon after the starting signal, the Hare sprinted far ahead and decided to take a brief nap under a shady oak tree.', 'Thỏ vì quá tự phụ vào tốc độ bẩm sinh của mình nên đã nhận lời thách đấu không chút đắn đo. Ngay sau hiệu lệnh xuất phát, Thỏ phóng vụt lên phía trước rồi quyết định đánh một giấc ngủ ngắn dưới bóng râm của cây sồi.', '[{"word":"swiftness","meaning":"Sự nhanh nhẹn, tốc độ cao"},{"word":"sprinted","meaning":"Chạy nước rút, phóng vọt đi"}]'::jsonb),
  ('6ff69fdd-a4bb-54f9-95d4-a29aeb9726e4', 'read-en-tortoise-hare', 3, 'Meanwhile, the Tortoise kept plodding on steadily without pausing for a single moment. When the Hare finally awoke from his slumber, he rushed towards the finish line only to see the Tortoise comfortably resting as the victor.', 'Trong lúc đó, Rùa vẫn kiên trì từng bước vững chắc không ngừng nghỉ một giây nào. Khi Thỏ cuối cùng tỉnh dậy khỏi giấc ngủ, chú vội vã lao về phía vạch đích nhưng chỉ thấy Rùa đã thảnh thơi nghỉ ngơi trong tư cách người chiến thắng.', '[{"word":"plodding","meaning":"Bước đi nặng nhọc nhưng kiên trì"},{"word":"slumber","meaning":"Giấc ngủ say"},{"word":"victor","meaning":"Người chiến thắng vinh quang"}]'::jsonb),
  ('d37e5c1b-74a2-5fe8-85f6-6e5b7725e053', 'read-en-alice-rabbit-hole', 1, 'Alice was beginning to get very tired of sitting by her sister on the riverbank, and of having nothing to do. Once or twice she had peeped into the book her sister was reading, but it had no pictures or conversations in it.', 'Alice bắt đầu cảm thấy rất mệt mỏi khi phải ngồi cạnh chị gái bên bờ sông mà chẳng có việc gì để làm. Một hai lần cô bé đã liếc nhìn vào cuốn sách chị đang đọc, nhưng trong đó chẳng hề có tranh ảnh hay những lời đối thoại nào.', '[{"word":"riverbank","meaning":"Bờ sông, bến nước"},{"word":"peeped","meaning":"Liếc trộm, nhìn lén"}]'::jsonb),
  ('0954dcd9-cd27-55ec-a28f-9d3c08414445', 'read-en-alice-rabbit-hole', 2, 'Suddenly, a White Rabbit with curious pink eyes ran close by her. It took a pocket-watch out of its waistcoat pocket, looked at it with anxiety, and hurried away into a large rabbit-hole under the hedge.', 'Bất thình lình, một chú Thỏ Trắng với đôi mắt màu hồng kỳ lạ chạy vụt qua sát cạnh cô. Chú rút một chiếc đồng hồ quả quýt ra khỏi túi áo gi-lê, nhìn vào nó với vẻ bồn chồn lo lắng, rồi vội vã chui tọt vào một chiếc hang thỏ lớn bên dưới hàng rào cây.', '[{"word":"waistcoat","meaning":"Áo gi-lê cài khuy"},{"word":"anxiety","meaning":"Sự lo âu, bồn chồn"}]'::jsonb),
  ('9d4f5f33-9d7f-5750-a94d-5b71ad76a32b', 'read-en-shakespeare-stage', 1, 'All the world''s a stage, and all the men and women merely players. They have their exits and their entrances, and one man in his time plays many different parts across his life journey.', 'Cả thế gian này tựa như một sân khấu kịch, và mọi đàn ông lẫn đàn bà chỉ là những diễn viên. Họ có những lần bước ra và những lần rút lui, và một con người trong cuộc đời mình sẽ sắm rất nhiều vai diễn khác nhau trong suốt hành trình sống.', '[{"word":"merely","meaning":"Chỉ là, thuần tuý"},{"word":"players","meaning":"Diễn viên sân khấu kịch"}]'::jsonb),
  ('466558e2-0193-54c0-b41a-e5956a860eb7', 'read-en-science-habits', 1, 'Neuroscientists have discovered that habits emerge because the human brain constantly seeks ways to conserve energy. An efficient brain transforms routine behavioral sequences into automatic reflexes.', 'Các nhà khoa học thần kinh phát hiện ra rằng thói quen xuất hiện bởi vì bộ não con người luôn tìm kiếm cách để bảo tồn năng lượng. Một bộ não hoạt động hiệu quả sẽ biến chuỗi hành vi thường nhật thành những phản xạ tự động.', '[{"word":"conserve","meaning":"Bảo tồn, gìn giữ năng lượng"},{"word":"sequences","meaning":"Chuỗi trình tự liên tiếp"}]'::jsonb),
  ('5a9704d9-5ba1-5fd3-ae06-ef1212329f8b', 'read-en-walden-woods', 1, 'I went to the woods because I wished to live deliberately, to front only the essential facts of life, and see if I could not learn what it had to teach, and not, when I came to die, discover that I had not lived.', 'Tôi tìm về chốn rừng sâu bởi vì tôi muốn sống một cách có chủ đích, để đối diện trực tiếp với những thực tại cốt lõi của đời sống, và xem liệu tôi có thể học được những điều cuộc đời muốn dạy, để khi nhắm mắt xuôi tay, tôi không nhận ra mình chưa từng thực sự sống.', '[{"word":"deliberately","meaning":"Có chủ đích, suy xét cẩn trọng"},{"word":"essential","meaning":"Cốt lõi, thiết yếu nhất"}]'::jsonb),
  ('036ae8f4-0799-5711-9232-8cf4625aea65', 'read-zh-saiweng', 1, '从前，边塞住着一位老翁。一天，他家的马无缘无故跑到了胡人的领地，邻居们都来安慰他。老翁却笑着说：“这怎么就不能是一件好事呢？”', 'Thuở xưa, nơi biên ải có một ông lão sinh sống. Một hôm, con ngựa nhà ông chẳng rõ duyên cớ chạy lạc vào lãnh thổ của người Hồ, hàng xóm đều đến an ủi. Ông lão lại cười bảo: "Việc này biết đâu lại là chuyện tốt?"', '[{"word":"无缘无故","meaning":"Vô duyên vô cớ, không có lý do"},{"word":"领地","meaning":"Lãnh địa, vùng đất"}]'::jsonb),
  ('a90bfdea-d037-5e85-8a8a-f8adb9efab66', 'read-zh-saiweng', 2, '过了几个月，那匹马不仅自己回来了，还带回了一匹胡人的骏马。好事与坏事在生活中往往可以相互转化，不可因一时的得失而过于悲喜。', 'Mấy tháng sau, con ngựa đó chẳng những tự quay về, mà còn dẫn theo một con tuấn mã của người Hồ. Chuyện vui và việc buồn trong đời thường chuyển hoá lẫn nhau, chớ nên vì được mất nhất thời mà quá bi luỵ hay mừng rỡ.', '[{"word":"骏马","meaning":"Tuấn mã, ngựa tốt chạy nhanh"},{"word":"转化","meaning":"Chuyển hoá, thay đổi trạng thái"}]'::jsonb),
  ('ec323c09-b93d-590f-808d-dcc031c02306', 'read-ja-momotaro', 1, '昔々、ある所におじいさんとおばあさんが住んでいました。おじいさんは山へ柴刈りに、おばあさんは川へ洗濯に行きました。', 'Ngày xửa ngày xưa, ở một ngôi làng nọ có một ông lão và một bà lão sinh sống. Ông lão lên núi đốn củi, còn bà lão ra bờ sông giặt giũ quần áo.', '[{"word":"柴刈り","meaning":"Đốn củi, nhặt cành cây khô"},{"word":"洗濯","meaning":"Giặt giũ đồ"}]'::jsonb),
  ('7949e625-bcef-53bb-8dab-b858d815f7c6', 'read-ja-momotaro', 2, 'おばあさんが洗濯をしていると、川上から大きな桃がどんぶらこ、どんぶらこと流れてきました。家に持ち帰って切ってみると、中から元気な男の子が生まれました。', 'Khi bà lão đang giặt áo thì từ thượng nguồn dòng sông, một quả đào khổng lồ bồng bềnh trôi xuôi về phía bà. Đem về nhà bổ ra xem thì thấy một cậu bé khoẻ mạnh kháu khỉnh sinh ra từ bên trong.', '[{"word":"どんぶらこ","meaning":"Từ tượng hình chỉ vật bồng bềnh dập dềnh trôi trên nước"},{"word":"持ち帰る","meaning":"Mang về nhà"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET original_text = EXCLUDED.original_text, translated_text = EXCLUDED.translated_text, vocab_notes = EXCLUDED.vocab_notes;

-- 11. ĐỀ THI LUYỆN THI IELTS & BỘ CÂU HỎI HỌC THUẬT (Kỳ vọng: 5 đề thi, 20 câu hỏi)
INSERT INTO public.exam_tests (
  id, exam_id, skill_id, title, description, time_allowed_minutes, total_questions, is_published,
  passage_title, passage_content, passage_summary, category_tags, audio_url
) VALUES

  (
    'read_cam18_p1', 'ielts', 'reading', 'Lịch sử Cây Chè và Con đường Trà Mã Cổ Đạo', 'Cambridge IELTS Academic 18 - Passage 1', 20, 6, true,
    'The Ancient Tea Horse Road: Heritage and Trade', 'Tea has shaped human civilizations for millennia. Originating in the lush highlands of southwestern China, wild tea plants (Camellia sinensis) were first harvested not as a leisurely brew, but as a bitter medicinal herb. According to legendary records dating back to Emperor Shennong around 2737 BCE, leaves fell into a cauldron of boiling water, unleashing a refreshing fragrance that marked the serendipitous birth of tea consumption.

By the Tang Dynasty (618–907 CE), tea had transformed from an elite remedy into a national obsession. Buddhist monks embraced the beverage to maintain alertness during marathon meditation sessions, fostering an elaborate culture of tea preparation. However, it was during the Song Dynasty that tea acquired geopolitical importance through the creation of the Tea Horse Road (Cha Ma Gu Dao).

Stretching across thousands of perilous kilometers through snowy passes, sheer gorges, and dense subtropical jungles, the Tea Horse Road linked Sichuan and Yunnan provinces with the Tibetan plateau. Tibetans required tremendous amounts of brick tea to balance their high-meat, high-fat diet in sub-zero altitudes. In exchange, the Chinese imperial military urgently needed hardy Tibetan mountain horses to defend their northern frontiers against nomadic incursions. An elaborate barter exchange flourished: one prime Tibetan warhorse could command up to sixty kilograms of compressed brick tea.

The human porters and mule caravans faced unimaginable hardships. Caravans navigated cliffside paths barely two feet wide, suspended precariously over roaring currents of the Yangtze and Mekong rivers. Modern preservationists consider this ancient network a cultural conduit comparable in significance to the Silk Road, demonstrating how a simple beverage bridged disparate geographies and empires.', NULL, '["True/False/Not Given","Điền từ","Lịch sử"]'::jsonb, NULL
  ),
  (
    'read_coral_p2', 'ielts', 'reading', 'Bảo Tồn Rạn San Hô và Giải Pháp Công Nghệ Sinh Học', 'Cambridge IELTS Academic 17 - Passage 2', 20, 5, true,
    'Coral Reef Restoration: Engineering Resilient Ecosystems', 'Coral reefs occupy less than one percent of the ocean floor, yet they harbor an astonishing twenty-five percent of all marine species. Often celebrated as the underwater rainforests of our planet, these biological wonderlands provide vital coastal protection, sustain global fishing economies, and generate crucial revenue from eco-tourism.

Tragically, rising seawater temperatures triggered by atmospheric greenhouse gas emissions have induced unprecedented global coral bleaching events. When marine temperatures exceed normal thresholds by as little as one degree Celsius for sustained periods, corals expel their symbiotic microalgae (zooxanthellae), stripping them of their vibrant pigmentation and their primary photosynthetic nutrient source. Left untreated, starved coral skeletons turn bone-white and perish.

In response, marine biologists at the Australian Institute of Marine Science have pioneered assisted gene flow and selective cross-breeding. By cultivating thermally resilient "super corals" that have naturally survived in hyper-warm tidal lagoons, scientists can selectively breed larvae with elevated thermal tolerance. When reseeded onto damaged reefs, these engineered colonies demonstrate a significantly reduced susceptibility to bleaching.

Nevertheless, conservationists emphasize that localized biological interventions are fundamentally stopgap measures. Without aggressive global commitments to carbon neutrality, even the hardiest laboratory-bred corals will eventually succumb to acidified and overheated seas.', NULL, '["Matching Headings","Multiple Choice","Sinh học môi trường"]'::jsonb, NULL
  ),
  (
    'list_sec1_homestay', 'ielts', 'listening', 'Đăng Ký Lưu Trú Homestay Tại New Zealand', 'Cambridge IELTS 18 - Listening Section 1', 10, 5, true,
    'Section 1: International Student Homestay Application', 'OFFICER: Good morning. Welcome to Auckland International Student Services. How can I help you today?
STUDENT: Hello. I am Keiko Tanaka. That is T-A-N-A-K-A. I study Environmental Science. I arrive on the 15th of February. Strictly no seafood, and I am allergic to cats.', NULL, '["Form Completion","Thông tin cá nhân","Section 1"]'::jsonb, NULL
  ),
  (
    'write_task2_ai', 'ielts', 'writing', 'Trí Tuệ Nhân Tạo và Tương Lai Giáo Dục', 'IELTS Academic Writing Task 2 - Essay', 40, 1, true,
    NULL, 'Some people believe that artificial intelligence and automated teaching applications will soon replace human teachers in classrooms. Others argue that human educators remain irreplaceable in developing emotional intelligence and critical thinking.

Discuss both views and give your own opinion. Write at least 250 words.', NULL, '["Task 2","Nghị luận xã hội","Agree or Disagree"]'::jsonb, NULL
  ),
  (
    'speak_cue_travel', 'ielts', 'speaking', 'Chuyến Đi Đáng Nhớ và Văn Hóa Bản Địa', 'IELTS Speaking Full 3 Parts', 14, 3, true,
    NULL, 'Part 1: Do you prefer travelling alone or with friends? What was the most interesting place you visited recently?

Part 2 (Cue Card): Describe a memorable journey you made by public transport. You should say: Where you went, What transport you used, Who was with you, and explain why this journey was so memorable to you.

Part 3: How has modern high-speed transportation changed tourism? Do you think remote natural attractions should limit visitor numbers to prevent pollution?', NULL, '["Part 1, 2, 3","Cue Card","Du lịch & Văn hóa"]'::jsonb, NULL
  )
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, passage_title = EXCLUDED.passage_title, passage_content = EXCLUDED.passage_content;

INSERT INTO public.exam_questions (id, test_id, question_number, type, question_text, options, correct_answer, explanation, category_tag, passage_section_ref) VALUES

  ('ad23c00c-bd3b-56cb-bf54-7848890de82f', 'read_cam18_p1', 1, 'true_false_not_given', 'Wild tea leaves were originally consumed as a medicine rather than a recreational beverage.', '[{"id":"TRUE","text":"TRUE"},{"id":"FALSE","text":"FALSE"},{"id":"NOT GIVEN","text":"NOT GIVEN"}]'::jsonb, 'TRUE', 'Đoạn 1 nêu rõ: "wild tea plants were first harvested not as a leisurely brew, but as a bitter medicinal herb" -> Khớp hoàn toàn với phát biểu.', 'True/False/Not Given', 'Đoạn 1'),
  ('83ace0b2-83db-55cc-bbd4-3ba5a3d67cb4', 'read_cam18_p1', 2, 'true_false_not_given', 'Emperor Shennong intentionally conducted experiments to discover tea.', '[{"id":"TRUE","text":"TRUE"},{"id":"FALSE","text":"FALSE"},{"id":"NOT GIVEN","text":"NOT GIVEN"}]'::jsonb, 'FALSE', 'Đoạn 1 ghi: "leaves fell into a cauldron of boiling water... marked the serendipitous (tình cờ) birth of tea", chứng minh đây là việc ngẫu nhiên chứ không phải chủ đích làm thí nghiệm.', 'True/False/Not Given', 'Đoạn 1'),
  ('6a177277-3ef1-5f3f-8531-57380e5131e8', 'read_cam18_p1', 3, 'true_false_not_given', 'Tibetan warriors taught Chinese soldiers advanced equestrian tactics.', '[{"id":"TRUE","text":"TRUE"},{"id":"FALSE","text":"FALSE"},{"id":"NOT GIVEN","text":"NOT GIVEN"}]'::jsonb, 'NOT GIVEN', 'Bài đọc chỉ nhắc người Trung Hoa đổi trà lấy ngựa Tây Tạng để phòng thủ biên giới, không hề đề cập việc người Tây Tạng dạy chiến thuật cưỡi ngựa cho quân đội.', 'True/False/Not Given', 'Đoạn 3'),
  ('7bb72e99-3a3f-5318-98a2-dc6aedca9666', 'read_cam18_p1', 4, 'multiple_choice', 'Why did Tibetan people have an urgent demand for brick tea?', '[{"id":"A","text":"It was used as religious offering in Buddhist temples"},{"id":"B","text":"It helped counteract their heavy meat and fat diet in cold weather"},{"id":"C","text":"It was much cheaper than drinking fresh mountain water"},{"id":"D","text":"It was required by the Chinese emperor as yearly tax"}]'::jsonb, 'B', 'Đoạn 3 giải thích: "Tibetans required tremendous amounts of brick tea to balance their high-meat, high-fat diet in sub-zero altitudes."', 'Multiple Choice', 'Đoạn 3'),
  ('0d1af8d1-2f42-55d5-870a-3f130d8ded06', 'read_cam18_p1', 5, 'fill_blank', 'A single high-quality Tibetan warhorse could be traded for approximately sixty kilograms of compressed ______ tea.', '[]'::jsonb, 'brick', 'Đoạn 3 ghi: "one prime Tibetan warhorse could command up to sixty kilograms of compressed brick tea."', 'Điền từ', 'Đoạn 3'),
  ('2d68c661-95eb-578d-872a-8853a92876a5', 'read_cam18_p1', 6, 'fill_blank', 'Historical experts compare the cultural and commercial importance of the Tea Horse Road to the famous ______ Road.', '[]'::jsonb, 'Silk', 'Đoạn 4 ghi: "Modern preservationists consider this ancient network a cultural conduit comparable in significance to the Silk Road."', 'Điền từ', 'Đoạn 4'),
  ('dba27f3a-43cc-5c9b-8dd5-75c96f2d898c', 'read_coral_p2', 1, 'multiple_choice', 'What percentage of marine species depend on coral reefs for survival?', '[{"id":"A","text":"Less than one percent"},{"id":"B","text":"Approximately ten percent"},{"id":"C","text":"Twenty-five percent"},{"id":"D","text":"Fifty percent"}]'::jsonb, 'C', 'Đoạn 1 nêu: "yet they harbor an astonishing twenty-five percent of all marine species."', 'Multiple Choice', 'Đoạn 1'),
  ('93980a73-f5dd-5768-af06-79b04ae7d4ff', 'read_coral_p2', 2, 'true_false_not_given', 'Coral bleaching happens when corals lose their symbiotic algae due to elevated temperatures.', '[{"id":"TRUE","text":"TRUE"},{"id":"FALSE","text":"FALSE"},{"id":"NOT GIVEN","text":"NOT GIVEN"}]'::jsonb, 'TRUE', 'Đoạn 2 giải thích rõ khi nhiệt độ tăng, san hô đào thải vi tảo cộng sinh (zooxanthellae), dẫn tới mất màu và chết đói.', 'True/False/Not Given', 'Đoạn 2'),
  ('37a0733e-d65e-5714-9fd5-265ed96e38ad', 'read_coral_p2', 3, 'fill_blank', 'Biologists cultivate resilient colonies by sourcing corals that have naturally adapted in warm tidal ______.', '[]'::jsonb, 'lagoons', 'Đoạn 3 có viết: "survived in hyper-warm tidal lagoons".', 'Điền từ', 'Đoạn 3'),
  ('bf1d13e1-547b-5e55-8238-27497128f2bc', 'read_coral_p2', 4, 'true_false_not_given', 'Selective breeding has eliminated the need to curb global carbon emissions.', '[{"id":"TRUE","text":"TRUE"},{"id":"FALSE","text":"FALSE"},{"id":"NOT GIVEN","text":"NOT GIVEN"}]'::jsonb, 'FALSE', 'Đoạn 4 nhấn mạnh đây chỉ là giải pháp tạm thời (stopgap measures) và không thể thay thế việc cắt giảm khí thải.', 'True/False/Not Given', 'Đoạn 4'),
  ('b8537beb-3e1b-599c-87db-b800b381b11f', 'read_coral_p2', 5, 'multiple_choice', 'What is the main conclusion of the passage regarding coral reef preservation?', '[{"id":"A","text":"Marine tourism must be completely prohibited worldwide"},{"id":"B","text":"Bio-engineering must be paired with aggressive carbon reduction"},{"id":"C","text":"Natural corals cannot adapt to any thermal variation"},{"id":"D","text":"Artificial reefs are far superior to natural reefs"}]'::jsonb, 'B', 'Ý chính đoạn cuối: giải pháp sinh học phải đi liền với cam kết giảm thải carbon toàn cầu.', 'Multiple Choice', 'Đoạn 4'),
  ('1939c233-f52c-514a-958f-c6a800554142', 'list_sec1_homestay', 1, 'fill_blank', 'Student Full Name: Keiko ______', '[]'::jsonb, 'Tanaka', 'Nghe đoạn đánh vần: T-A-N-A-K-A.', 'Form Completion', ''),
  ('2e58177c-f5c5-557c-a200-379994a033d0', 'list_sec1_homestay', 2, 'fill_blank', 'Academic Program: Environmental ______', '[]'::jsonb, 'Science', 'Học sinh nói: "I am enrolled in the Environmental Science undergraduate diploma."', 'Form Completion', ''),
  ('a373d052-3dc2-57ea-b0ba-e1a856b8ce47', 'list_sec1_homestay', 3, 'fill_blank', 'Arrival date in Auckland: 15th of ______', '[]'::jsonb, 'February', 'Học sinh nói: "My flight arrives on the 15th of February."', 'Form Completion', ''),
  ('35a96922-fe27-59bb-896e-4e6d5f905b0c', 'list_sec1_homestay', 4, 'fill_blank', 'Dietary restriction: Cannot consume ______', '[]'::jsonb, 'seafood', 'Học sinh nói rõ: "I do not eat seafood."', 'Form Completion', ''),
  ('87513015-b962-542e-8bd3-33e97e191915', 'list_sec1_homestay', 5, 'multiple_choice', 'What pet allergy does the student specify?', '[{"id":"A","text":"Dogs"},{"id":"B","text":"Birds"},{"id":"C","text":"Cats"},{"id":"D","text":"Rabbits"}]'::jsonb, 'C', 'Học sinh nói: "Also, I am allergic to cats."', 'Multiple Choice', ''),
  ('3be86502-c37e-51cc-bfb3-d985eaeef93f', 'write_task2_ai', 1, 'essay', 'Viết bài luận nghị luận Task 2 bàn về 2 quan điểm và nêu lập trường cá nhân (tối thiểu 250 từ):', '[]'::jsonb, 'Tiêu chuẩn chấm điểm: Task Response, Coherence & Cohesion, Lexical Resource, Grammar Range.', 'Bố cục bài luận 4 đoạn: 1. Mở bài; 2. Thân bài 1 (lợi thế của AI); 3. Thân bài 2 (vai trò giáo viên người thật); 4. Kết bài.', 'IELTS Writing Task 2', ''),
